In each of these types there is a unique (up to isomorphism) sextic del Pezzo surface.
Moreover, the surfaces of types $0$, $2$, $3$, and $5$ are toric
(in particular, the surface of type~5 is the weighted projective plane~${\mathbb{P}}(1,2,3)$, 
see~\cite[Example~5.8]{kawamata2015multi} for an alternative description of its derived category).
The surfaces of type~1 and~4 are not toric.

Semiorthogonal decomposition for a sextic del Pezzo surface
\label{subsection:derived-x}

Now we apply the above computations to describe the derived category of a sextic du Val del Pezzo surface $X$.
The main result of this section is the next theorem.


\begin{theorem}
\label{theorem:dbx}
Let $X$ be a sextic du Val del Pezzo surface over an algebraically closed field~$\kk$, and let $\pi \colon \tX \to X$ be its minimal resolution of singularities.
Then there is a unique semiorthogonal decomposition
\begin{equation}\label{eq:dbx}
\bD(X) = \langle \cA_1, \cA_2, \cA_3 \rangle,
\end{equation}
such that $\pi_*(\tcA_i) = \cA_i$ and $\pi^*(\cA_i \cap \bD^\perf(X)) \subset \tcA_i$, where $\tcA_i$ are the components of~\eqref{eq:dbtx}.
The components~$\cA_i$ are admissible with projection functors of finite cohomological amplitude, 
and are equivalent to products of derived categories of finite-dimensional algebras as indicated 
in the next table:
\begin{equation*}\def\arraystretch{1.2}
\begin{array}{|c|c|c|c|}
\hline
\text{Type of $X$} & \cA_1 & \cA_2 & \cA_3 \\
\hline 
0 & \bD(\kk) & \bD(\kk) \times \bD(\kk) \times \bD(\kk) & \bD(\kk) \times \bD(\kk) \\
\hline
1 & \bD(\kk) & \bD(\kk) \times \bD(\kk) \times \bD(\kk) & \bD(\kk[t]/t^2) \\
\hline
2 & \bD(\kk) & \bD(\kk[t]/t^2) \times \bD(\kk) & \bD(\kk)  \times \bD(\kk) \\
\hline
3 & \bD(\kk) & \bD(\kk[t]/t^2) \times \bD(\kk) & \bD(\kk[t]/t^2) \\
\hline
4 & \bD(\kk) & \bD(\kk[t]/t^3) & \bD(\kk)  \times \bD(\kk) \\
\hline
5 & \bD(\kk) & \bD(\kk[t]/t^3) & \bD(\kk[t]/t^2) \\
\hline
\end{array}
\end{equation*}
The categories $\cA_i^\perf := \cA_i \cap \bD^\perf(X)$ form a semiorthogonal decomposition of the perfect category
\begin{equation*}
\bD^\perf(X) = \langle \cA_1^\perf, \cA_2^\perf, \cA_3^\perf \rangle.
\end{equation*}
\end{theorem}

The proof takes the rest of this subsection.
We start with some preparations.

Consider the semiorthogonal decomposition~\eqref{eq:dbtx}.
Since $\tX$ is smooth, every component $\tcA_i$ of $\bD(\tX)$ is admissible, hence~\eqref{eq:dbtx} is a strong semiorthogonal decomposition 
in the sense of~\cite[Definition~2.6]{kuznetsov2011base}.
Therefore, by~\cite[Proposition~4.2]{kuznetsov2011base} it extends to a semiorthogonal decomposition of the bounded above derived category
\begin{equation}\label{eq:dbtx-}
\bD^-(\tX) = \langle \tcA_1^-, \tcA_2^-, \tcA_3^- \rangle.
\end{equation}
The next lemma describes the intersections of its components with the kernel category of the pushforward functor $\pi_*$.
Recall that $\bDelta$ denotes the set of all $(-2)$-curves defined on $\tX$. 
We denote by $\bDelta_2 \subset \bDelta$ the subset formed by those of the curves $\Delta_{12}$ and $\Delta_{23}$ 
that are defined on $\tX$ and by $\bDelta_3 \subset \bDelta$ its complement.


\begin{lemma}
\label{lemma:ker-pis}
We have 
\begin{equation*}
\tcA_1^- \cap \Ker \pi_* = 0,
\qquad 
\tcA_2^- \cap \Ker \pi_* = \langle \cO_{\Delta}(-1) \rangle^\oplus_{\Delta \in \bDelta_2},
\quand
\tcA_3^- \cap \Ker \pi_* = \langle \cO_{\Delta}(-1) \rangle^\oplus_{\Delta \in \bDelta_3}.
\end{equation*}
Moreover, for any $\cF \in \Ker\pi_* \subset \bD^-(\tX)$ there is a canonical direct sum decomposition 
\begin{equation*}
\cF = \cF_2 \oplus \cF_3
\end{equation*}
with $\cF_j \in \tcA_j^- \cap \Ker \pi_*$.
\end{lemma}
\begin{proof}
By Lemma~\ref{lemma:pi-properties}
an object $\cF \in \bD^-(\tX)$ is in $\Ker\pi_*$ if and only if every its cohomology sheaf~$\cH^j(\cF)$ 
is an iterated extension of sheaves $\cO_\Delta(-1)$
where $\Delta$ run over the set $\bDelta$ of all $(-2)$-curves on~$\tX$.
Note that $\cO_\Delta(-1) \in \tcA_2$ for $\Delta \in \bDelta_2$ by~\eqref{eq:e12} and~\eqref{eq:e23}, while $\cO_\Delta(-1) \in \tcA_3$ for $\Delta \in \bDelta_3$ by~\eqref{eq:e123}.
Moreover, the subcategories generated by the sheaves $\cO_\Delta(-1)$ with $\Delta \in \bDelta_2$ and $\Delta \in \bDelta_3$ are completely orthogonal, since the supports of these sheaves do not intersect.
This last observation shows that any $\cF \in \Ker\pi_*$ decomposes as $\cF_2 \oplus \cF_3$ with the required properties (just take $\cF_2$ and $\cF_3$ to be the components of $\cF$ 
supported on the union of the curves $\Delta$ from $\bDelta_2$ and $\bDelta_3$ respectively).
\end{proof}

Another useful observation is the following.

\begin{lemma}\label{lemma:ker-pis-orthogonality}
We have $\Hom(\tcA_i^-,\tcA_j^- \cap \Ker \pi_*) = 0$ for any $i \ne j$.
\end{lemma}
\begin{proof}
Since $\tcA_i^-$ is generated by an exceptional collection of line bundles and $\tcA_j^- \cap \Ker \pi_*$ is generated by sheaves $\cO_\Delta(-1)$ for $\Delta \in \bDelta_j$,
it is enough to check that any of the line bundles generating $\tcA_i^-$ restricts trivially to any curve $\Delta$ from $\bDelta_j$.

For $i = 1$ this is evident; for $i = 2$ we have
$(h-e_k)\cdot \Delta_{123} = (h - e_k)(h - e_1 - e_2 - e_3) = 1 - 1 = 0$,
and for $i = 3$ we have 
$h\cdot (e_k - e_l) = 0$
and
$(2h - e_1 - e_2 - e_3) \cdot (e_k - e_l) = 1 - 1 = 0$.
\end{proof}



Now we can show that~\eqref{eq:dbtx-} induces a semiorthogonal decomposition of~$\bD^-(X)$.
Denote by $\tilde\alpha_i$ the projection functors of the decomposition~\eqref{eq:dbtx-}.
By~\cite[Proposition~4.2]{kuznetsov2011base} the projection functors of~\eqref{eq:dbtx} are given 
by the restrictions of $\tilde\alpha_i$ to $\bD(\tX)$.

\begin{proposition}\label{proposition:sod-dbx-}
The subcategories $\cA_i^- = \{ \cF \in \bD^-(X) \mid  \pi^*(\cF) \in \tcA_i^- \} \subset \bD^-(X)$ form a semiorthogonal decomposition
\begin{equation*}
\bD^-(X) = \langle \cA_1^-, \cA_2^-, \cA_3^- \rangle
\end{equation*}
with projection functors given by
\begin{equation}
\label{eq:alpha}
\alpha_i = \pi_* \circ \tilde\alpha_i \circ \pi^*.
\end{equation}
Moreover, we have
\begin{equation}\label{eq:pis-ai}
\pi_*(\tcA_i^-) = \cA_i^-.
\end{equation}
\end{proposition}
\begin{proof}
By Lemma~\ref{lemma:pi-properties} the functor $\pi^* \colon \bD^-(X) \to \bD^-(\tX)$ is fully faithful, hence the subcategories $\cA_i^-$ are semiorthogonal.

Let us prove~\eqref{eq:pis-ai}.
For this take any object $\cF \in \tcA_i^-$ and consider the standard triangle
\begin{equation*}
\pi^*(\pi_*\cF) \to \cF \to \cG.
\end{equation*}
Then, of course, $\cG \in \Ker\pi_*$.
By Lemma~\ref{lemma:ker-pis} we have $\cG = \cG_2 \oplus \cG_3$ with~$\cG_j \in \tcA_j^- \cap \Ker \pi_*$.
If~$j \ne i$ then~$\Ext^\bullet(\cF,\cG_j) = 0$ by Lemma~\ref{lemma:ker-pis-orthogonality} and $\Ext^\bullet(\pi^*(\pi_*\cF),\cG_j) = 0$ since $\cG_j \in \Ker  \pi_*$.
It follows from the above triangle that $\Hom(\cG,\cG_j) = 0$, hence $\cG_j = 0$ since it is a direct summand of $\cG$.
Therefore we have $\cG \in \tcA_i^-$, hence $\pi^*(\pi_*\cF) \in \tcA_i^-$, hence $\pi_*\cF \in \cA_i^-$ by definition of the latter.
This proves an inclusion $\pi_*(\tcA_i^-) \subset \cA_i^-$.
The other inclusion follows from~\eqref{eq:pis-pis-id}.

Now let us decompose any $\cF \in \bD^-(X)$.
For this take $\tcF := \pi^*(\cF) \in \bD^-(\tX)$ and consider its decomposition with respect to~\eqref{eq:dbtx-}.
It is given by a chain of morphisms 
\begin{equation*}
0 = \tcF_3 \rightarrow \tcF_2 \rightarrow \tcF_1 \rightarrow \tcF_0 = \tcF,
\end{equation*}
whose cones are $\tilde\alpha_i(\tcF) \in \tcA_i^-$.
Pushing it forward to $X$, we obtain a chain of morphisms 
\begin{equation*}
0 = \pi_*(\tcF_3) \rightarrow \pi_*(\tcF_2) \rightarrow \pi_*(\tcF_1) \rightarrow \pi_*(\tcF_0) = \pi_*(\tcF) \cong \cF,
\end{equation*}
whose cones are $\pi_*(\tilde\alpha_i(\tcF)) \cong \pi_*(\tilde\alpha_i(\pi^*\cF)) \in \pi_*(\tcA_i^-) = \cA_i^-$.
This proves the semiorthogonal decomposition and shows that its projection functors are given by~\eqref{eq:alpha}.
\end{proof}

And now we can construct the required semiorthogonal decomposition of~$\bD(X)$.

\begin{proposition}
\label{proposition:sod-dbx}
The subcategories 
\begin{equation*}
\cA_i := \cA_i^- \cap \bD(X) = \{ \cF \in \bD(X) \mid \pi^*(\cF) \in \tcA_i^- \} \subset \bD(X)
\end{equation*}
provide a semiorthogonal decomposition~\eqref{eq:dbx}.
Its projection functors $\alpha_i$ are given by~\eqref{eq:alpha}; they preserve boundedness and have finite cohomological amplitude.
Finally, $\cA_i = \pi_*(\tcA_i)$.
\end{proposition}
\begin{proof}
For the first claim it is enough to check that the projection functors $\alpha_i$ preserve boundedness.
Take any $\cF \in \bD^{[a,b]}(X)$ and consider $\pi^*(\cF) \in \bD^{(-\infty,b]}(\tX)$.
By projection formula $\pi_*(\pi^*(\cF)) \cong \cF$, hence by Lemma~\ref{lemma:spectral} we have $\tau^{\le a-1}(\pi^*(\cF)) \in \Ker \pi_*$.
Consider the triangle
\begin{equation*}
\tilde\alpha_i(\tau^{\le a-1}(\pi^*(\cF))) \to \tilde\alpha_i(\pi^*(\cF)) \to \tilde\alpha_i(\tau^{\ge a}(\pi^*(\cF)))
\end{equation*}
obtained by applying the projection functor $\tilde\alpha_i$ to the canonical truncation triangle.
By Lemma~\ref{lemma:ker-pis} the functor $\tilde\alpha_i$ preserves~$\Ker\pi_*$, hence the first term of the triangle is in $\Ker \pi_*$.
Therefore, applying the pushforward we obtain an isomorphism 
\begin{equation*}
\alpha_i(\cF) = \pi_*(\tilde\alpha_i(\pi^*(\cF))) \cong \pi_*(\tilde\alpha_i(\tau^{\ge a}(\pi^*(\cF))).
\end{equation*}
So, it remains to note that $\tau^{\ge a}(\pi^*(\cF)) \in \bD^{[a,b]}(\tX)$,
hence $\pi_*(\tilde\alpha_i(\tau^{\ge a}(\pi^*(\cF)))$ is bounded, since both $\tilde\alpha_i$ and $\pi_*$ preserve boundedness.
Moreover, if the cohomological amplitude of $\tilde\alpha_i$ is $(p,q)$ 
(it is finite since~$\tX$ is smooth, see~\cite[Proposition~2.5]{kuznetsov2008resolution}), then
$\pi_*(\tilde\alpha_i(\tau^{\ge a}(\pi^*(\cF))) \in \bD^{[a+p,b+q+1]}(X)$.
In particular, $\alpha_i$ has finite cohomological amplitude.

Let us prove the last claim.
By~\eqref{eq:pis-ai} we have $\pi_*(\tcA_i) \subset \cA_i^-$, and since $\pi_*$ preserves boundedness, we have $\pi_*(\tcA_i) \subset \cA_i$.
To check that this inclusion is an equality, take any $\cF \in \cA_i$.
By Corollary~\ref{corollary:pis-epi} there exists $\tcF \in \bD(\tX)$ such that $\cF \cong \pi_*(\tcF)$.
Let $\cG$ be the cone of the natural morphism $\pi^*\cF \to \tcF$.
Then $\cG \in \Ker  \pi_*$.
Moreover, $\tilde\alpha_i(\cG) \in \Ker \pi_*$ by Lemma~\ref{lemma:ker-pis}, hence applying the functor $\pi_* \circ \tilde\alpha_i$ 
to the distinguished triangle $\pi^*\cF \to \tcF \to \cG$, we deduce an isomorphism $\cF \cong \alpha_i(\cF) \cong \pi_*(\tilde\alpha_i(\tcF))$,
and it remains to note that $\tilde\alpha_i(\tcF) \in \tcA_i$.
\end{proof}



Next, we identify the categories $\cA_1$, $\cA_2$, and $\cA_3$ constructed in Proposition~\ref{proposition:sod-dbx} 
with the corresponding products of $\bD(\kk[t]/t^m)$.
By Proposition~\ref{proposition:tcai-auslander} each category $\tcA_i$ is equivalent to a product of derived categories $\bD(\tR_m)$ of Auslander algebras $\tR_m$.
Take one of these and denote by $\tilde\gamma \colon \bD(\tR_m) \to \bD(\tX)$ its embedding functor.
Let 
\begin{equation*}
\pi_{m*} \colon \bD^-(\tR_m) \to \bD^-(\kk[t]/t^m)
\qquad \text{and} \qquad
\pi_m^* \colon \bD^-(\kk[t]/t^m) \to \bD^-(\tR_m)
\end{equation*}
be the functors described in Appendix~\ref{appendix:auslander}, see equation~\eqref{eq:pms}.
Note that $\pi_m^*$ is left adjoint to~$\pi_{m*}$.

\begin{proposition}
\label{proposition:gamma}
The functor 
\begin{equation}\label{def:gamma}
\gamma := \pi_* \circ \tilde\gamma \circ \pi_m^* \colon \bD^-(\kk[t]/t^m) \to \bD^-(X).
\end{equation}
is fully faithful and preserves boundedness.
Moreover, the diagrams
\begin{equation}
\label{eq:gamma-tgamma}
\vcenter{\xymatrix@C=5em{
\bD^-(\tR_m) \ar[r]^-{\tilde\gamma} \ar[d]_{\pi_{m*}} &
\bD^-(\tX) \ar[d]^{\pi_{*}} 
\\
\bD^-(\kk[t]/t^m) \ar[r]^{\gamma} &
\bD^-(X)
}}
\qquad\text{and}\qquad
\vcenter{\xymatrix@C=5em{
\bD^-(\tR_m) \ar[r]^-{\tilde\gamma} &
\bD^-(\tX)  
\\
\bD^-(\kk[t]/t^m) \ar[r]^{\gamma} \ar[u]^{\pi_m^{*}} &
\bD^-(X) \ar[u]_{\pi^{*}}
}}
\end{equation}
are both commutative.
\end{proposition}
\begin{proof}
By definition $\gamma \circ \pi_{m*} = \pi_* \circ \tilde\gamma \circ \pi_m^* \circ \pi_{m*}$, so for commutativity of the first diagram it is enough to check that for any $M \in \bD^-(\tR_m)$ 
the cone of the canonical morphism $\pi_m^*(\pi_{m*}M) \to M$ is killed by the functor $\pi_* \circ \tilde\gamma$.
But this cone, by Proposition~\ref{proposition:auslander-localization} is contained in the subcategory generated by the simple modules $S_1,\dots,S_{m-1}$ over $\tR_m$.
By Remark~\ref{remark:delta-simples} the functor $\tilde\gamma$ takes these modules to sheaves $\cO_\Delta(-1)$ 
for appropriate $(-2)$-curves $\Delta$ on $\tX$, and the functor $\pi_*$ kills every $\cO_\Delta(-1)$ by Lemma~\ref{lemma:pi-properties}.

For commutativity of the second diagram note that by Proposition~\ref{proposition:auslander-localization} the image of the functor~$\pi_m^*$ 
is the left orthogonal ${}^\perp\langle S_1,\dots, S_{m-1} \rangle \subset \bD^-(\tR_m)$ of the subcategory generated by the simple modules.
Therefore, using Lemma~\ref{lemma:ker-pis-orthogonality} and Remark~\ref{remark:delta-simples} we deduce that the image of $\tilde\gamma \circ \pi_m^*$ is contained 
in the left orthogonal ${}^\perp \langle \cO_\Delta(-1) \rangle \subset \bD^-(\tX)$ of the subcategory generated by all $(-2)$-curves $\Delta$.
Hence, by Lemma~\ref{lemma:pi-properties} it is contained in the image of $\pi^* \colon \bD^-(X) \to \bD^-(\tX)$.
Thus, the functor $\pi^* \circ \pi_*$ is identical on the image of $\tilde\gamma \circ \pi_m^*$, hence 
$\tilde\gamma \circ \pi_m^* \cong 
\pi^* \circ \pi_* \circ \tilde\gamma \circ \pi_m^* \cong 
\pi^* \circ \gamma$,
and so the second diagram commutes.

Let us show that $\gamma$ is fully faithful.
Indeed, by commutativity of the second diagram in~\eqref{eq:gamma-tgamma}, this follows from full faithfulness of the functors $\pi_m^*$ (Proposition~\ref{proposition:auslander-localization}), 
$\tilde\gamma$ (Proposition~\ref{proposition:tcai-auslander}), and $\pi^*$ (Lemma~\ref{lemma:pi-properties}).


Finally, let us show that $\gamma$ preserves boundedness.
Indeed, take any $N \in \bD(\kk[t]/t^m)$.
By Proposition~\ref{proposition:auslander-localization} there exists $M \in \bD(\tR_m)$ such that $N \cong \pi_{m*}(M)$.
Then $\gamma(N) = \gamma(\pi_{m*}(M))$ and by commutativity of the first diagram this is the same as $\pi_*(\tilde\gamma(M))$.
We know that $\tilde\gamma(M)$ is bounded by Proposition~\ref{proposition:tcai-auslander}, hence so is $\pi_*(\tilde\gamma(M)) = \gamma(N)$.
\end{proof}

Now we are ready to describe the components $\cA_i$ of~\eqref{eq:dbx}.
Let $\tcA_i = \bD(\tR_{m_1}) \times \dots \times \bD(\tR_{m_s})$ be the corresponding component of~\eqref{eq:dbtx}.
Let $\tilde\gamma_j \colon \bD(\tR_{m_j}) \to \bD(\tX)$ be the corresponding embedding functors and 
let $\gamma_j \colon \bD(\kk[t]/t^{m_j}) \to \bD(X)$ be the embeddings constructed in Proposition~\ref{proposition:gamma}.

\begin{proposition}
\label{proposition:sod-cai}
The fully faithful functors $\gamma_1,\dots,\gamma_s$ induce a completely orthogonal decomposition 
\begin{equation*}
\cA_i = \bD(\kk[t]/t^{m_1}) \times \dots \times \bD(\kk[t]/t^{m_s}).
\end{equation*}
\end{proposition}
\begin{proof}
By definition $\gamma_j = \pi_* \circ \tilde\gamma_j \circ \pi_{m_j}^*$ and its image is contained in $\pi_*(\tcA_i^-) = \cA_i^-$.
Moreover, since $\gamma_j$ preserves boundedness, it actually is in $\cA_i$.

To see that the images of $\gamma_j$ are orthogonal, it is enough to check orthogonality of the images of functors $\pi^* \circ \gamma_j = \tilde\gamma_j \circ \pi_{m_j}^*$,
which follows immediately from Proposition~\ref{proposition:tcai-auslander}.


Finally, let us show the generation.
Assume $\cF \in \cA_i$ and let $\cG \in \tcA_i$ be such that $\pi_*\cG \cong \cF$ (it exists by Proposition~\ref{proposition:sod-dbx}). 
Then $\cG$ has a direct sum decomposition $\cG \cong \oplus \cG_j$, 
where $\cG_j \in \tilde\gamma_j(\bD(\tR_{m_j}))$ (Proposition~\ref{proposition:tcai-auslander}).
Therefore, $\cF \cong \pi_*(\cG) \cong \oplus \pi_*(\cG_j)$.
Moreover, $\pi_*(\cG_j) \in \pi_*(\tilde\gamma_j(\bD(\tR_{m_j}))) = \gamma_j(\bD(\kk[t]/t^m))$,
hence objects $\cF_j = \pi_*(\cG_j)$ give the required decomposition of $\cF$.
\end{proof}



Now we can finish the proof of Theorem~\ref{theorem:dbx}.

\begin{lemma}
\label{lemma:cai-admissible}
The subcategories $\cA_i \subset \bD(X)$ in~\eqref{eq:dbx} are admissible.
\end{lemma}
\begin{proof}
Consider the semiorthogonal decompositions
\begin{equation*}
\bD(\tX) = \langle \tcA_3 \otimes \omega_\tX, \tcA_1, \tcA_2 \rangle
\qquand
\bD(\tX) = \langle \tcA_2 \otimes \omega_\tX, \tcA_3 \otimes \omega_\tX, \tcA_1 \rangle,
\end{equation*}
obtained from~\eqref{eq:dbtx} by mutations.
Since $\omega_\tX \cong \pi^*\omega_X$ and $\omega_X$ is a line bundle on $X$, we have 
\begin{equation*}
\pi_*(\tcA_i \otimes \omega_\tX) = \pi_*(\tcA_i) \otimes \omega_X = \cA_i \otimes \omega_X,
\end{equation*}
hence the arguments of this subsection also prove semiorthogonal decompositions


\begin{equation}\label{eq:dbx-other}
\bD(X) = \langle \cA_3 \otimes \omega_X, \cA_1, \cA_2 \rangle
\qquand
\bD(X) = \langle \cA_2 \otimes \omega_X, \cA_3 \otimes \omega_X, \cA_1 \rangle.
\end{equation}
Since the twist by $\omega_X$ is an autoequivalence of $\bD(X)$, these decompositions together with~\eqref{eq:dbx} 
show that each $\cA_i$ is admissible.
Indeed, (up to a twist) each $\cA_i$ appears in one of the three decompositions on the left, and in one on the right,
hence it is both left and right admissible.
\end{proof}

\begin{proof}[Proof of Theorem~\textup{\ref{theorem:dbx}}]
The semiorthogonal decomposition~\eqref{eq:dbx} is constructed in Proposition~\ref{proposition:sod-dbx}.
The equality $\cA_i = \pi_*(\tcA_i)$, which implies uniqueness of the decomposition, 
and finiteness of cohomological amplitude of the projection functors $\alpha_i$ are also proved there.
Admissibility of $\cA_i$ is proved in Lemma~\ref{lemma:cai-admissible}.
The structure of the components $\cA_i$ is described in Proposition~\ref{proposition:sod-cai}.
The required semiorthogonal decomposition of~$\bD^\perf(X)$ is obtained by~\cite[Proposition~4.1]{kuznetsov2011base}
and the embedding $\pi^*(\cA_i^\perf) \subset \tcA_i$ is evident from the definition
of the categories $\cA_i$ (see Propositions~\ref{proposition:sod-dbx-} and~\ref{proposition:sod-dbx}).
\end{proof}


For further convenience, we would like to rewrite the semiorthogonal decomposition~\eqref{eq:dbx} geometrically.

\begin{corollary}
\label{corollary:dbx-z2-z3}
For every sextic du Val del Pezzo surface $X$ over an algebraically closed field $\kk$ there are 
zero-dimensional Gorenstein schemes $Z_1$, $Z_2$, $Z_3$ of lengths $1$, $3$, and $2$ respectively, such that $\cA_i \cong \bD(Z_i)$ and
\begin{equation}
\label{eq:dbx-dz}
\bD(X) = \langle \bD(Z_1), \bD(Z_2), \bD(Z_3) \rangle.
\end{equation}
The scheme structure of $Z_i$ depends on the type of $X$ as follows:
\begin{equation*}\def\arraystretch{1.2}
\begin{array}{|c|c|c|c|}
\hline
\text{Type of $X$} & Z_1 & Z_2 & Z_3 \\
\hline 
0 & \Spec(\kk) & \Spec(\kk) \sqcup \Spec(\kk) \sqcup \Spec(\kk) & \Spec(\kk) \sqcup \Spec(\kk) \\
\hline
1 & \Spec(\kk) & \Spec(\kk) \sqcup \Spec(\kk) \sqcup \Spec(\kk) & \Spec(\kk[t]/t^2) \\
\hline
2 & \Spec(\kk) & \Spec(\kk[t]/t^2) \sqcup \Spec(\kk) & \Spec(\kk)  \sqcup \Spec(\kk) \\
\hline
3 & \Spec(\kk) & \Spec(\kk[t]/t^2) \sqcup \Spec(\kk) & \Spec(\kk[t]/t^2) \\
\hline
4 & \Spec(\kk) & \Spec(\kk[t]/t^3) & \Spec(\kk)  \sqcup \Spec(\kk) \\
\hline
5 & \Spec(\kk) & \Spec(\kk[t]/t^3) & \Spec(\kk[t]/t^2) \\
\hline
\end{array}
\end{equation*}
\end{corollary}

Since $X$ is Gorenstein, we can produce yet another semiorthogonal decomposition by dualization.
Recall that $\cF^\vee$ denotes the derived dual of $\cF$, see Section~\ref{subsection:duality}.

\begin{proposition}\label{proposition:dbx-dual}
If $X$ is a sextic del Pezzo surface over an algebraically closed field, there is a semiorthogonal decomposition 
\begin{equation}
\label{eq:dbx-dual}
\bD(X) = \langle \cA_3^\vee, \cA_2^\vee, \cA_1^\vee \rangle,
\end{equation}
where
\begin{equation*}
\cA_i^\vee := \{ \cF \in \bD(X) \mid \cF^\vee \in \cA_i \} \cong \bD(Z_i),
\end{equation*}
and $\cA_i$ are the components of~\eqref{eq:dbx}.
Moreover, this semiorthogonal decomposition 
is right mutation-dual to~\eqref{eq:dbx}, i.e., $\cA_1^\vee = \cA_1$, $\cA_2^\vee = \LL_{\cA_1}(\cA_2)$ and $\cA_3^\vee = \LL_{\cA_1}(\LL_{\cA_2}(\cA_3))$.
\end{proposition}
\begin{proof}
As we discussed in Section~\ref{subsection:duality}, the functor $\cF \mapsto \cF^\vee$ is an equivalence $\bD(X)^{\mathrm{opp}} \to \bD(X)$ (since~$X$ is Gorenstein).
When applied to the semiorthogonal decomposition of Corollary~\ref{corollary:dbx-z2-z3}, it gives~\eqref{eq:dbx-dual} 
with~$\cA_i^\vee \cong \bD(Z_i)^{\mathrm{opp}}$.
Since $Z_1$, $Z_2$ and $Z_3$ are themselves Gorenstein, we have $\bD(Z_i)^{\mathrm{opp}} \cong \bD(Z_i)$.

Finally, let us prove mutation-duality of~\eqref{eq:dbx-dual} and~\eqref{eq:dbx}.
It follows from~\eqref{eq:alpha} that $\LL_{\cA_i} \circ \pi_* \cong \pi_* \circ \LL_{\tcA_i}$ and $\LL_{\tcA_i} \circ \pi^* \cong \pi^* \circ \LL_{\cA_i}$.
So, the required result follows easily from Lemma~\ref{lemma:dual-sod-tx}.
\end{proof}

Moduli of rank 1 sheaves
\label{subsection:moduli}


For a sheaf $\cF$ on $X$ we denote by 
\begin{equation*}
h_\cF(t) := \chi(\cF(-tK_X)) \in \ZZ[t],
\end{equation*}
the Hilbert polynomial of $\cF$ with respect to the anticanonical polarization of $X$.
This is a quadratic polynomial with the leading coefficient equal to $r(\cF)\cdot K_X^2/2 = 3r(\cF)$.
Note that 
\begin{equation}\label{eq:hox}
h_{\cO_X}(t) = 3t(t+1) + 1.
\end{equation}

For each $d \in \ZZ$ we consider the polynomial
\begin{equation}\label{eq:hd}
h_d(t) := (3t + d)(t+1) 

\in \ZZ[t].
\end{equation}
An elementary verification shows
\begin{equation}\label{eq:hd-inequalities}
h_4(t) > h_3(t) > h_2(t) > h_{\cO_X}(t) > h_4(t-1) > h_3(t-1) > h_2(t-1)
\qquad\text{for all $t \gg 0$.}
\end{equation} 

Below we will be interested in semistable sheaves on $X$ with Hilbert polynomial $h_d(t)$.

\begin{lemma}
\label{lemma:hd-stable}
A sheaf $\cF$ on $X$ with Hilbert polynomial $h_d(t)$ is Gieseker semistable if and only if it is Gieseker stable and if and only if it is torsion-free.
\end{lemma}
\begin{proof}
As we observed above, the leading monomial of $h_d(\cF)$ being $3t^2$ means that $r(\cF) = 1$.
Therefore, such a sheaf $\cF$ could (and will) be destabilized only by a subsheaf of rank~0, i.e., by a torsion sheaf.
Thus, $\cF$ is (semi)stable if and only if it is torsion-free.
\end{proof}


Recall the sheaves $\cE_z$, $\fE_Z$, and $\fE_{Z_d}$ on $X$ introduced 
in Lemma~\ref{lemma:e-z-small}, \eqref{def:fez}, and~\eqref{eq:cezd} respectively.

\begin{lemma}\label{lemma:hilbert-fz}
Let $d \in \{2, 3\}$.
For any closed point $z \in Z_d$ the sheaf $\cE_z$ is stable with $h_{\cE_z}(t) = h_d(t)$.
Its derived dual~$\cE_z^\vee$ is a stable sheaf with $h_{\cE_z^\vee}(t) = h_d(-t-1) = h_{6-d}(t-1)$.
Furthermore, the sheaf $\fE_{Z_d}$ is semistable with $h_{\fE_{Z_d}} = \ell(Z_d)h_d$.
\end{lemma}
\begin{proof}
As we already mentioned, $r(\cE_z) = 1$ implies the leading monomial of $h_{\cE_z}$ equals $3t^2$.
So, to show an equality of polynomials $h_{\cE_z} = h_d$ it is enough to check that they take the same values at points~$t = 0$ and~$t = -1$.
In other words, we have to check that 
\begin{equation*}
\chi(X,\cE_z) = h_d(0) = d
\qquand
\chi(X,\cE_z \otimes \omega_X) = h_d(-1) = 0.
\end{equation*}
The first is proved in Lemma~\ref{lemma:e-z-small}, and the second follows from $\cE_z \in \cA_d$ and decompositions~\eqref{eq:dbx-other}.


The sheaf $\cE_z$ is torsion free since by Lemma~\ref{lemma:e-z-small} it is the direct image of a line bundle 
under a dominant map $\pi$, hence is stable by Lemma~\ref{lemma:hd-stable}.
Furthermore, it follows from Proposition~\ref{proposition:e-z-big} that $\fE_{Z_d}$ is semistable with the same reduced Hilbert polynomial.

To show that $\cE_z^\vee$ is a sheaf, consider the connected component $Z$ of~$Z_d$ containing~$z$ and
note that the sheaf $\fE_Z$ is filtered by $\cE_z$, hence $\fE_Z^\vee$ is filtered by $\cE_z^\vee$.
But $\fE_Z$ is locally free by Proposition~\ref{proposition:e-z-big}, 
hence~$\fE_Z^\vee$ is a sheaf, hence $\cE_z^\vee$ is a sheaf as well.













Stability of $\cE_z^\vee$ is proved in the same way as that of $\cE_z$; and the fact that its Hilbert polynomial equals $h_d(-t-1)$ follows easily from Serre duality (Proposition~\ref{proposition:serre-gorenstein}).
\end{proof}




Denote by 
\begin{equation}
\label{eq:mdx}
\cM_d(X) := \cM_{X,-K_X}(h_d)
\end{equation}
the moduli space of Gieseker semistable sheaves on $X$ with Hilbert polynomial $h_d(t)$ (with respect to the anticanonical polarization of $X$).
We aim at description of these moduli spaces for $d  \in \{2,3,4\}$.


We start by describing their closed points.

\begin{lemma}
\label{lemma:md-points}
Let $\cF$ be a torsion free sheaf on $X$ whose Hilbert polynomial is $h_d(t)$ with $d \in \{2, 3, 4 \}$.
$(i)$ If $d \in \{2, 3\}$ there is a unique closed point $z \in Z_d$ such that $\cF \cong \cE_z$.
\newline
$(ii)$ If $d \in \{3, 4\}$ there is a unique closed point $z \in Z_{6-d}$ such that $\cF \cong \cE_z^\vee \otimes \omega_X^{-1}$.
\end{lemma}
\begin{proof}
First, assume $d = 2$.
Let us show that $\cF \in \cA_2$. 
By Corollary~\ref{corollary:a-as-orthogonals} for this we should check that~$\Ext^\bullet(\cF,\cO_X) = \Ext^\bullet(\fE_{Z_3},\cF) = 0$.
By Lemma~\ref{lemma:hd-stable} the sheaf $\cF$ is stable.
By Lemma~\ref{lemma:hilbert-fz} and~\eqref{eq:hd-inequalities}, we have $\frac1{\ell(Z_3)}h_{\fE_{Z_3}}(t) > h_\cF(t) > h_{\cO_X}(t)$, hence by semistability 
\begin{equation*}
\Hom(\fE_{Z_3},\cF) = \Hom(\cF,\cO_X) = 0.
\end{equation*}
Similarly, $\frac1{\ell(Z_3)}h_{\fE_{Z_3}}(t-1) < h_\cF(t) < h_{\cO_X}(t+1)$, hence
\begin{equation*}
\Hom(\cF,\fE_{Z_3}(K_X)) = \Hom(\cO_X(-K_X),\cF) = 0.
\end{equation*}
By Serre duality on $X$ (note that $\fE_{Z_3}$ is locally free and use Proposition~\ref{proposition:serre-gorenstein}) we deduce 
\begin{equation*}
\Ext^2(\fE_{Z_3},\cF) = \Ext^2(\cF,\cO_X) = 0.
\end{equation*}
Since (again by Serre duality and local freeness of $\cO_X$ and $\fE_{Z_3}$) we can have 
nontrivial $\Ext^p(\fE_{Z_3},\cF)$ and~$\Ext^p(\cF,\cO_X)$ only for $p \in \{0,1,2\}$,
it remains to check that 
\begin{equation*}
\chi(\fE_{Z_3},\cF) = \chi(X,\cF(K_X)) = 0.
\end{equation*}
The second equality here just follows from $h_\cF(-1) = h_2(-1) = 0$,
and the first follows from Lemma~\ref{lemma:chi-ez-f} and $h_2(0) + h_2(-1) - 2 = 0$.

Thus, we have shown that $\cF \in \cA_2 \cong \bD(Z_2)$. 
Since $Z_2$ is a zero-dimensional scheme, any object in~$\bD(Z_2)$ is isomorphic 
to an iterated extension of shifts of structure sheaves of closed points in~$Z_2$.
By Lemma~\ref{lemma:e-z-small} these sheaves correspond to sheaves~$\cE_z \in \cA_2$, hence $\cF$ is an extension of shifts of those.
Since $\cF$ is a pure sheaf of rank equal to~1, 

we conclude that $\cF \cong \cE_z$ for a closed point $z \in Z_2$.

The case $d = 3$ is treated similarly. 







The same argument with~$\cA_2$ and~$\cA_3$ replaced by~$\cA_2^\vee \otimes \omega_X^{-1}$ and~$\cA_3^\vee \otimes \omega_X^{-1}$ 
and~\eqref{eq:dbx} replaced by a twist of~\eqref{eq:dbx-dual} proves part~$(ii)$.
\end{proof}


Below we consider families of objects parameterized by a scheme $S$.
Let $p_S \colon M \to S$ be a morphism of schemes.
For each geometric point $s \in S$ we denote by $M_s$ the scheme-theoretic fiber of $M$ over $s$ 
and by~$i_{M_s} \colon M_s \hookrightarrow M$ its embedding.
The embedding $s \hookrightarrow S$ is denoted simply by $i_s$.


\begin{lemma}
\label{lemma:fiberwise}
Assume $\cF \in \bD^-(M)$ and $M$ is proper over $S$, and in $(ii)$ and $(iii)$ that $M$ is flat over $S$.
\begin{enumerate}
\item[$(i)$] 
If $i_{M_s}^*(\cF) \in \bD^{\le p_0}(M_s)$ for some integer $p_0$ and all geometric points $s \in S$, then $\cF \in \bD^{\le p_0}(M)$.
In particular, if $i_{M_s}^*(\cF) = 0$ for all geometric points $s \in S$, then $\cF = 0$.
\item[$(ii)$] 
If for all geometric points $s \in S$ the pullback $i_{M_s}^*(\cF)$ is a pure sheaf 
such that $H^k(M_s, i_{M_s}^*\cF) = 0$ for all~$k \ne 0$ and $\dim H^0(M_s,i_{M_s}^*\cF) = r$ for a constant $r$,
then $p_{S*}(\cF)$ is a vector bundle of rank~$r$ on~$S$.
\item[$(iii)$] 
If for any geometric point $s \in S$ there is a point $m \in M_s$ such that $i_{M_s}^*(\cF) \cong \cO_m$, then 
there is a unique section $\varphi \colon S \to M$ of the projection $p_S$ and a line bundle $\cL \in \Pic(S)$ such that $\cF \cong \varphi_*\cL$.
\end{enumerate}
\end{lemma}
\begin{proof}
$(i)$ 
Let $\cH^k(\cF)$ be the top nonzero cohomology sheaf of $\cF$; by assumption it is a coherent sheaf on $M$.
Let $s \in S$ be a geometric point in the image of the support of~$\cH^k(\cF)$ under the map $p_S \colon M \to S$.
The spectral sequence
\begin{equation}
\label{eq:spectral}
L_qi_{M_s}^*\cH^p(\cF) \Rightarrow \cH^{p-q}(i_{M_s}^*\cF)
\end{equation}
implies that $\cH^k(i_{M_s}^*\cF) \cong L_0i_{M_s}^*\cH^k(\cF) \ne 0$, hence $k \le p_0$.

$(ii)$ Set $\cG := p_{S*}(\cF)$.
By base change we have an isomorphism 
\begin{equation*}
H^\bullet(M_s,i_{M_s}^*(\cF)) \cong i_s^* (\cG).
\end{equation*}
By assumption, the left hand side is a vector space of dimension $r$ in degree $0$.
By~$(i)$ we have

$\cG \in \bD^{\le 0}(S)$.
Moreover the spectral sequence~\eqref{eq:spectral} with $M = S$ and $\cF = \cG$
\begin{equation*}
L_q i_s^* \cH^p(\cG) \Rightarrow \cH^{p-q}(i_s^*(\cG)) \cong H^{p-q}(M_s, i_{M_s}^*(\cF))
\end{equation*}
shows that $L_0i_s^*\cH^0(\cG) \cong H^0(M,i_{M_s}^*\cF)$ and $L_1i_s^*\cH^0(\cG) = 0$.
Therefore, by Serre's criterion the sheaf~$\cH^0(\cG)$ is a vector bundle of rank~$r$.
Looking again at the spectral sequence, we see that the canonical map $\cG \to \cH^0(\cG)$ induces an isomorphism $i_s^*\cG \to i_s^*(\cH^0(\cG))$ for each $s \in S$, 
hence by part $(i)$ we have an isomorphism $\cG \cong \cH^0(\cG)$.
Thus $p_{S*}(\cF) = \cG$ is a vector bundle of rank $r$.

$(iii)$ 
By part $(i)$ we have $\cF \in \bD^{\le 0}(M)$ and by part~$(ii)$ we know that $p_{S*}(\cF)$ is a line bundle.
Denote it by $\cL$.
Then replacing the object $\cF$ by~$\cF \otimes p_S^*\cL^{-1}$, we may assume that $p_{S*}(\cF) \cong \cO_S$.
We have by adjunction a map $\cO_{M} = p_S^*\cO_S \to \cF \to \cH^0(\cF)$ 
that restricts to the fiber $M_s$ over a geometric point~\mbox{$s \in S$} as the natural map $\cO_{M_s} \to \cO_m$.
Therefore, it is fiberwise surjective, hence by part $(i)$ applied to its cone it is surjective on $M$.
So, $\cH^0(\cF) \cong \cO_\Gamma$ is the structure sheaf of a closed subscheme $\Gamma \subset M$.

By the assumption for each geometric point $s \in S$ we have $i_s^*\cO_\Gamma \cong \cO_m$. 

Therefore the map $p_S\vert_\Gamma \colon \Gamma \to S$ is finite and flat of degree~1.
By $(ii)$ we have $p_{S*}\cO_\Gamma \cong \cO_S$, so it follows that the map $p_S\vert_\Gamma \colon \Gamma \to S$ is an isomorphism.
Therefore, $\Gamma$ is the image of a section $\varphi \colon S \to M$ of the morphism $p_S$.

The above argument proves $\cH^0(\cF) \cong \cO_\Gamma \cong \varphi_*\cO_S$.
Restricting the triangle $\tau^{\le -1}\cF \to \cF \to \cH^0(\cF)$ to an arbitrary fiber $M_s$ we deduce that $i_{M_s}^*(\tau^{\le -1}\cF) = 0$ for any $s \in S$, hence $\tau^{\le -1}\cF = 0$ by part $(i)$.
Therefore $\cF \cong \varphi_*\cO_S$.
\end{proof}

Now we return to a sextic del Pezzo surface $X$ and the moduli spaces $\cM_d(X)$ defined by~\eqref{eq:mdx}.
Recall the sheaves $\cE_{Z_d}$ on $X \times Z_d$ constructed in Proposition~\ref{proposition:fm-zd}.

\begin{theorem}
\label{theorem:moduli}
Let $X$ be a sextic du Val del Pezzo surface over an algebraically closed field $\kk$. 
The moduli spaces $\cM_2(X)$, $\cM_3(X)$, and $\cM_4(X)$ are fine moduli spaces. 
Moreover,
\newline$(i)$
$\cM_2(X) \cong \cM_4(X) \cong Z_2$ and the sheaves $\cE_{Z_2}$ and $\cE_{Z_2}^\vee \otimes \omega_X^{-1}$ are the corresponding universal families;
\newline$(ii)$
$\cM_3(X) \cong Z_3$ and the sheaves $\cE_{Z_3}$ and $\cE_{Z_3}^\vee \otimes \omega_X^{-1}$ are two universal families for this moduli problem.
\end{theorem}
\begin{proof}
Let $S$ be an arbitrary base scheme and $\cF$ a coherent sheaf on $X \times S$ flat over $S$ and such that 
for any geometric point $s \in S$ the restriction $\cF_s = i_{X \times s}^*(\cF)$ is a semistable (i.e., torsion free) sheaf with Hilbert polynomial~$h_d(t)$ for $d \in \{2,3\}$.
By Lemma~\ref{lemma:md-points} it follows that 
\begin{equation*}
\cF_s \cong \cE_z 
\end{equation*}
for a unique closed point $z \in Z_d$.

Consider the semiorthogonal decomposition
\begin{equation}\label{eq:dbx-s}
\bD(X \times S) = \langle \cA_{1S}, \cA_{2S}, \cA_{3S} \rangle = \langle \bD(S), \bD(Z_2 \times S), \bD(Z_3 \times S) \rangle,
\end{equation}
obtained by the base change $S \to \Spec(\kk)$ (\cite[Theorem~5.6]{kuznetsov2011base}) from~\eqref{eq:dbx-dz} 
(the second equality follows from \cite[Theorem~6.4]{kuznetsov2011base} and Proposition~\ref{proposition:fm-zd}).
Since by Proposition~\ref{proposition:fm-zd} the embedding functors of~\eqref{eq:dbx-dz} are the Fourier--Mukai functors given by the sheaves $\cE_{Z_d}$,
the embedding functors of~\eqref{eq:dbx-s} are given by the pullbacks $\cE_{Z_d} \boxtimes \cO_S$ of $\cE_{Z_d}$ via the maps $X \times Z_d \times S \to X \times Z_d$.

For any $\cF \in \bD(X \times S)$, a geometric point $s \in S$, and each $d' \in \{1,2,3\}$ we have by~\cite[(11)]{kuznetsov2011base} an isomorphism
\begin{equation*}
i_{Z_{d'} \times s}^*(\alpha_{d'S}(\cF)) \cong \alpha_{d'}(i_{X \times s}^*(\cF)) \in \bD(Z_{d'}),
\end{equation*}
where $\alpha_{d'} \colon \bD(X) \to \bD(Z_{d'})$ and $\alpha_{d'S} \colon \bD(X \times S) \to \bD(Z_{d'} \times S)$ are 
the projection functors of the semiorthogonal decompositions~\eqref{eq:dbx-dz} and~\eqref{eq:dbx-s} respectively.
Using this isomorphism for the sheaf~$\cF$ we started with, and taking into account Lemma~\ref{lemma:e-z-small}, we conclude that
\begin{equation*}
i_{Z_{d'} \times s}^*(\alpha_{d'S}(\cF)) \cong \alpha_{d'}(\cF_s) \cong \alpha_{d'}(\cE_z) \cong 
\begin{cases}
\cO_z, & \text{if $d' = d$},\\
0, & \text{otherwise}.
\end{cases}
\end{equation*} 
By Lemma~\ref{lemma:fiberwise}$(i)$ it follows that $\alpha_{d'S}(\cF) = 0$ when $d' \ne d$, hence 
\begin{equation*}
\cF \cong \Phi_{\cE_{Z_d} \boxtimes \cO_S}(\cF_d)
\end{equation*}
for some object $\cF_d \in \bD(Z_d \times S)$.
Moreover, the object $\cF_d$ is such that for any geometric point~$s \in S$ we have  $i_{Z_d \times s}^*(\cF_d) \cong \cO_z$ for some closed point~$z \in Z_d$.
By Lemma~\ref{lemma:fiberwise}$(iii)$ it follows that $\cF_d \cong \Gamma_{f_d*}\cL$, where $f_d \colon S \to Z_d$ is a morphism, $\Gamma_{f_d} \colon S \to Z_d \times S$ is its graph, and $\cL$ is a line bundle on $S$.
Therefore
\begin{equation*}
\cF \cong \Phi_{\cE_{Z_d} \boxtimes \cO_S}(\Gamma_{f_d*}\cL) 
\cong (\id_X \times f_d)^*\cE_{Z_d} \otimes p_S^*\cL.
\end{equation*}
This precisely means that the moduli functor $\cM_d(X)$ we are interested in is represented by the scheme~$Z_d$, 
and that $\cE_{Z_d}$ is a universal sheaf.

This proves the statement about~$\cM_2(X)$ and the first statement about~$\cM_3(X)$.
The same argument applied to the dual semiorthogonal decomposition~\eqref{eq:dbx-dual} instead of~\eqref{eq:dbx-dz} 
proves the statement about~$\cM_4(X)$ and the second statement about~$\cM_3(X)$.

\end{proof}





\begin{corollary}\label{corollary:tau-m3x}
There is an automorphism $\sigma \colon \cM_3(X) \to \cM_3(X)$ such that $\cE_{Z_3}^\vee \cong \sigma^*\cE_{Z_3} \otimes \omega_X$.
\end{corollary}
\begin{proof}
Both $\cE_{Z_3}$ and $\cE_{Z_3}^\vee \otimes \omega_X^{-1}$ are universal families on $\cM_3(X) \times X$, hence they differ only by an automorphism of $\cM_3(X)$ and a twist by a line bundle on it.
But since $\cM_3(X)$ is zero-dimensional, it has no non-trivial line bundles.
\end{proof}

Hilbert scheme interpretation
\label{subsection:hilbert}

Now consider the polynomial 
\begin{equation}\label{eq:hdprime}
h'_d(t) = dt + 1 \in \ZZ[t].
\end{equation} 
This is the Hilbert polynomial of a rational normal curve of degree $d$.

\begin{lemma}
Let $C \subset X \subset {\mathbb{P}}^6$ be a subscheme with Hilbert polynomial $h_C(t) = h'_d(t)$ and $1 \le d \le 3$.
Then $C$ is a connected arithmetically Cohen--Macaulay curve.
\end{lemma}
\begin{proof}
In cases $d = 1$ and $d = 2$ this is standard (see, e.g., \cite[Lemma~2.1.1]{kuznetsov2016hilbert}).
In case $d = 3$ the only other possibility for $C$ (see~\cite[\S1]{lehn2015twisted} and references therein) would be a union of a plane cubic curve with a point (possibly embedded).
But~$X$ is an intersection of quadrics by~\cite[Theorem~4.4]{hidaka1981normal} and contains no planes, so this is impossible.
\end{proof}

\begin{lemma}\label{lemma:oc-decomposition}
$(i)$ If $C \subset X$ is a curve with Hilbert polynomial $h'_d(t)$ with $d \in \{2,3\}$ then there is a unique closed point $z \in Z_d$ and an exact sequence
\begin{equation*}
0 \to \cE_z^\vee \to \cO_X \to \cO_C \to 0.
\end{equation*}
Conversely, any nonzero morphism $\cE_z^\vee \to \cO_X$ is injective with cokernel isomorphic to $\cO_C$.

$(ii)$ Similarly, if $L \subset X$ is a line, i.e., a curve with Hilbert polynomial $h'_1(t)$ then there are unique closed points $z_2 \in Z_2$ and $z_3 \in Z_3$ and an exact sequence
\begin{equation*}
0 \to \cE_{z_2} \to \cE_{z_3} \to \cO_L \to 0.
\end{equation*}
Conversely, any nonzero morphism $\cE_{z_2} \to \cE_{z_3}$ is injective with cokernel isomorphic to $\cO_L$.
\end{lemma}
\begin{proof}
For the first part of~$(i)$, by Lemma~\ref{lemma:md-points}$(ii)$ it is enough to show 
that $I_C \otimes \omega_X^{-1}$ is stable with Hilbert polynomial~$h_{6-d}(t)$.
Stability is clear by Lemma~\ref{lemma:hd-stable}, and the Hilbert polynomial evidently equals 
\begin{equation*}
h_{\cO_X}(t+1) - h'_d(t+1) = (3(t+1)(t+2) + 1) - (d(t+1) + 1) = (3t + 6 - d)(t + 1) = h_{6-d}(t).
\end{equation*}



For the first part of~$(ii)$ first note that by Serre duality 
\begin{equation*}
\Ext^\bullet(\cO_L,\cO_X) \cong \Ext^\bullet(\cO_X,\cO_L(K_X))^\vee = H^\bullet(L,\cO_L(-1)) = 0 
\end{equation*}
since $L \cong {\mathbb{P}}^1$ and $L \cdot K_X = -1$.
Thus by Theorem~\ref{theorem:dbx} the structure sheaf $\cO_L$ is contained in the subcategory~$\langle \cA_2, \cA_3 \rangle$ of $\bD(X)$.
Next, again by Serre duality
\begin{equation*}
\Ext^i(\cO_L,\fE_{Z_2}) \cong \Ext^{2-i}(\fE_{Z_2},\cO_L(K_X))^\vee.
\end{equation*}
Since $\fE_{Z_2}$ is a vector bundle and $L$ is a curve, the right hand side is zero unless $i \in \{1, 2\}$.
On the other hand, $\fE_{Z_2}$ is globally generated by Proposition~\ref{proposition:e-z-big} and~\eqref{eq:cezd}, while $\cO_L(K_X) \cong \cO_L(-1)$ has no global sections, hence for $i = 2$ the right hand side is also zero.
On the other hand, by Lemma~\ref{lemma:chi-ez-f} we have
\begin{equation*}
\chi(\fE_{Z_2},\cO_L(K_X)) = 2\chi(X,\cO_L(K_X)) + \chi(X,\cO_L(2K_X)) - 3r(\cO_L(K_X)) = 2 \cdot h'_1(-1) + h'_1(-2) = -1,
\end{equation*}
and we conclude that $\Ext^\bullet(\cO_L, \fE_{Z_2}) = \kk[-1]$.
This means that there is a unique closed point $z_2 \in Z_2$ and a unique extension
\begin{equation*}
0 \to \cE_{z_2} \to \cF \to \cO_L \to 0
\end{equation*}
such that $\cF \in \cA_3$. 
It remains to note that $\cF$ is a sheaf of rank 1, hence there is a unique $z_3 \in Z_3$ such that $\cF \cong \cE_{z_3}$.

The converse statements are evident.
\end{proof}


Consider the Hilbert scheme
\begin{equation}
\label{def:fd}
F_d(X) := \Hilb_{X,-K_X}(h'_d)
\end{equation} 
of subschemes of $X$ with Hilbert polynomial $h'_d(t)$.
Thus, $F_1(X)$ is the Hilbert scheme of lines, $F_2(X)$ is the Hilbert scheme of conics, and $F_3(X)$ is the Hilbert scheme of generalized twisted cubic curves on $X$.

Recall the notation $p_2$, $p_3$, $p_{23}$, $p_{X2}$, and $p_{X3}$ introduced before Lemma~\ref{lemma:ps-ez}.
By Lemma~\ref{lemma:ps-ez} the sheaves $p_{2*}\cE_{Z_2}$, $p_{3*}\cE_{Z_3}$ and $p_{23*}(p_{X2}^*\cE_{Z_2}^\vee \otimes p_{X3}^*\cE_{Z_3})$ 
are locally free of ranks $2$, $3$ and $1$ on $Z_2$, $Z_3$ and~$Z_2 \times Z_3$ respectively.

\begin{proposition}\label{proposition:fd-zd}
We have natural isomorphisms of Hilbert schemes
\begin{equation*}
F_1(X) \cong Z_2 \times Z_3,
\qquad
F_2(X) \cong {\mathbb{P}}_{Z_2}(p_{2*}\cE_{Z_2}),
\qquand 
F_3(X) \cong {\mathbb{P}}_{Z_3}(p_{3*}\cE_{Z_3}).
\end{equation*}
\end{proposition}
\begin{proof}
Assume $d \in \{2,3\}$.
Let $\cC \subset X \times S$ be a flat $S$-family of subschemes in $X$ with Hilbert polynomial~$h'_d(t)$.
Consider the decomposition of the structure sheaf $\cO_\cC \in \bD(X \times S)$ with respect to the semiorthogonal decomposition 
\begin{equation*}
\bD(X \times S) = \langle \cA_{3S}^\vee, \cA_{2S}^\vee, \cA_{1S}^\vee \rangle,
\end{equation*}
obtained from the decomposition of Proposition~\ref{proposition:dbx-dual} 
by the base change $S \to \Spec(\kk)$ via~\cite[Theorem~5.6]{kuznetsov2011base}.
The argument of Theorem~\ref{theorem:moduli} together with the result of Lemma~\ref{lemma:oc-decomposition}$(i)$ shows 
that there is a morphism $f_d \colon S \to Z_d$, a line bundle $\cF_d$ on $S$, and an exact sequence
\begin{equation*}
0 \to (\id_X \times f_d)^*(\cE_{Z_d}^\vee) \otimes p_S^*(\cF_d) \to \cO_{X \times S} \to \cO_\cC \to 0
\end{equation*}
The left arrow corresponds to a global section of the bundle $(\id_X \times f_d)^*(\cE_{Z_d}) \otimes p_S^*(\cF_d^\vee)$, i.e., to a morphism from $p_S^*\cF_d$ to $(\id_X \times f_d)^*(\cE_{Z_d})$.
We have 
\begin{equation*}
\Hom(p_S^*\cF_d,(\id_X \times f_d)^*(\cE_{Z_d})) \cong
\Hom(\cF_d,p_{S*}((\id_X \times f_d)^*(\cE_{Z_d}))) \cong
\Hom(\cF_d,f_d^*p_{d*}(\cE_{Z_d})),
\end{equation*}
where the first equality follows from adjunction and the second is the base change for the diagram
\begin{equation*}
\xymatrix@C=5em{
X \times S \ar[r]^-{\id_X \times f_d} \ar[d]_{p_S} & X \times Z_d \ar[d]^{p_d} \\
S \ar[r]^-{f_d} & Z_d
}
\end{equation*}
The flatness over $S$ of the cokernel $\cO_\cC$ of the morphism $(\id_X \times f_d)^*(\cE_{Z_d}^\vee) \otimes p_S^*(\cF_d) \to \cO_{X \times S}$ 
is equivalent to the corresponding morphism $\cF_d \to f_d^*p_{d*}\cE_{Z_d}$ being nonzero for every closed point $s \in S$.
Thus the Hilbert scheme functor $F_d(X)$ is isomorphic to the functor that associates to a scheme $S$ a morphism $f_d \colon S \to Z_d$ and a line subbundle in $f_d^*p_{d*}\cE_{Z_d}$, 
hence is represented by the projective bundle ${\mathbb{P}}_{Z_d}(p_{d*}\cE_{Z_d})$.

Now assume $d = 1$ and let $\cC \subset X \times S$ be a flat family of lines.
Decomposing $\cO_\cC$ with respect to~\eqref{eq:dbx-s} 
and using the argument of Theorem~\ref{theorem:moduli} together with the result of Lemma~\ref{lemma:oc-decomposition}$(ii)$,
we conclude that there are morphisms $f_2 \colon S \to Z_2$ and $f_3 \colon S \to Z_3$,
line bundles $\cF_2$ and $\cF_3$ on $S$, and an exact sequence
\begin{equation}\label{eq:o-lines}
0 \to (\id_X \times f_{2})^*(\cE_{Z_2}) \otimes p_S^*(\cF_2) \to (\id_X \times f_{3})^*(\cE_{Z_3}) \otimes p_S^*(\cF_3) \to \cO_\cC \to 0.
\end{equation}
Moreover, the pushforward to $S$ of this sequence gives (again by base change) an exact sequence
\begin{equation*}
0 \to f_{2}^*(p_{2*}\cE_{Z_2}) \otimes \cF_2 \to f_{3}^*(p_{3*}\cE_{Z_3}) \otimes \cF_3 \to \cO_S \to 0.
\end{equation*}
Since by Lemma~\ref{lemma:ps-ez} we know that $f_{d}^*(p_{d*}\cE_{Z_d})$ is a vector bundle of rank $d$ on $S$, the comparison of determinants gives  a relation
\begin{equation}\label{eq:f23-relation}
\cF_3^3 \otimes \cF_2^{-2} \cong f_{2}^*(\det(p_{2*}\cE_{Z_2})) \otimes f_{3}^*(\det(p_{3*}\cE_{Z_3})^{-1}).
\end{equation}
Denoting by $f_{23} \colon S \to Z_2 \times Z_3$ the map induced by $f_2$ and $f_3$, we deduce by adjunction and base change 
\begin{equation*}
\Hom(f_{2}^*(p_{2*}\cE_{Z_2}) \otimes \cF_2, f_{3}^*(p_{3*}\cE_{Z_3}) \otimes \cF_3) \cong

\Hom(\cF_2 \otimes \cF_3^\vee,f_{23}^*p_{23*}(p_{X2}^*\cE_{Z_2}^\vee \otimes p_{X3}^*\cE_{Z_3}))
\end{equation*}
and note that $f_{23}^*p_{23*}(p_{X2}^*\cE_{Z_2}^\vee \otimes p_{X3}^*\cE_{Z_3})$ is a line bundle (again by Lemma~\ref{lemma:ps-ez}).
The flatness over~$S$ of the cokernel $\cO_\cC$ of the morphism of~\eqref{eq:o-lines} is equivalent to the pointwise injectivity 
of the corresponding morphism $\cF_2 \otimes \cF_3^\vee \to f_{23}^*p_{23*}(p_{X2}^*\cE_{Z_2}^\vee \otimes p_{X3}^*\cE_{Z_3})$,
i.e., to this map being an isomorphism.
On the other hand, any line bundle on $S$ can be written as the tensor product of line bundles $\cF_2 \otimes \cF_3^\vee$ satisfying~\eqref{eq:f23-relation} in a unique way.
This shows that the Hilbert scheme functor is isomorphic to the functor that associates to a scheme $S$ a pair of morphisms $f_2 \colon S \to Z_2$ and $f_3 \colon S \to Z_3$,
hence is represented by $Z_2 \times Z_3$.
\end{proof}

\begin{remark}
\label{remark:f4}
With the same argument one can prove that $p_{2*}(\cE_{Z_2}^\vee \otimes \omega_X^{-1})$ is a rank-4 vector bundle on~$Z_2$ 
and that~$F_4(X) \cong {\mathbb{P}}_{Z_2}(p_{2*}(\cE_{Z_2}^\vee \otimes \omega_X^{-1}))$.
\end{remark}

Linear sections of ${\mathbb{P
}^2 \times {\mathbb{P}}^2$}\label{subsection:p2p2}

The simplest way to construct a sextic del Pezzo surface is by considering an intersection of ${\mathbb{P}}^2 \times {\mathbb{P}}^2$ 
with a linear subspace of codimension 2 in the Segre embedding.


We denote by $W_1$ and $W_2$ a pair of vector spaces of dimension 3 and let 
\begin{equation*}
{\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2) \hookrightarrow {\mathbb{P}}(W_1 \otimes W_2)
\end{equation*}
be the Segre embedding. 
To give its linear section of codimension 2, we need a two-dimensional subspace~$K \subset W_1^\vee \otimes W_2^\vee$.
We denote by $K^\perp \subset W_1 \otimes W_2$ its codimension 2 annihilator, and set
\begin{equation}\label{eq:xk}
X_K := ({\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)) \cap {\mathbb{P}}(K^\perp) \subset {\mathbb{P}}(W_1 \otimes W_2), 
\end{equation}
to be the corresponding linear section.

\begin{lemma}\label{lemma:xk-duval}
Assume the base field $\kk$ is algebraically closed.
The intersection $X_K$ defined by~\textup{\eqref{eq:xk}} is a sextic du Val del Pezzo surface if and only if 
\begin{itemize}
\item the line ${\mathbb{P}}(K)$ does not intersect the dual Segre variety ${\mathbb{P}}(W_1^\vee) \times {\mathbb{P}}(W_2^\vee) \subset {\mathbb{P}}(W_1^\vee \otimes W_2^\vee)$, and
\item the line ${\mathbb{P}}(K)$ is not contained in the discriminant cubic hypersurface $\cD_{W_1,W_2} \subset {\mathbb{P}}(W_1^\vee \otimes W_2^\vee)$.
\end{itemize}
Furthermore, $X_K$ is smooth if and only if the line ${\mathbb{P}}(K)$ is transversal to $\cD_{W_1,W_2}$.
\end{lemma}
\begin{proof}
First, let us show that the condition is necessary.
If ${\mathbb{P}}(K)$ intersects ${\mathbb{P}}(W_1^\vee) \times {\mathbb{P}}(W_2^\vee)$ then $K$ contains a bilinear form $b \in W_1^\vee \otimes W_2^\vee$ of rank 1, i.e., $b = \varphi_1 \otimes \varphi_2$, where $\varphi_i \in W_i^\vee$.
The zero locus of~$b$ on ${\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)$ is equal to $({\mathbb{P}}(\varphi_1^\perp) \times {\mathbb{P}}(W_2)) \cup ({\mathbb{P}}(W_1) \times {\mathbb{P}}(\varphi_2^\perp))$. 
Consequently, $X_K$ is its hyperplane section, hence is a union of two cubic scrolls, hence is not an integral surface.

Next, assume that ${\mathbb{P}}(K)$ is contained in $\cD_{W_1,W_2}$. 
Then there are three possibilities: either
\begin{itemize}
\item 
$K \subset w_1^\perp \otimes W_2^\vee$ for some $w_1 \in W_1$, or
\item 
$K \subset W_1^\vee \otimes w_2^\perp$ for some $w_2 \in W_2$, or
\item 
$K \subset \Ker(W_1^\vee \otimes W_2^\vee \to U_1^\vee \otimes U_2^\vee)$ for some 2-dimensional subspaces $U_1 \subset W_1$ and $U_2  \subset W_2$.
\end{itemize}
In the first case we have $\{w_1\} \times {\mathbb{P}}(W_2) \subset X_K$, in the second case ${\mathbb{P}}(W_1) \times \{w_2\} \subset X_K$, and in the third case ${\mathbb{P}}(U_1) \times {\mathbb{P}}(U_2) \subset X_K$,
so in all these cases the surface $X_K$ is not integral.

Now, let us show that the conditions are sufficient.
So, assume $K \subset W_1^\vee \otimes W_2^\vee$ is such that the line~${\mathbb{P}}(K)$ is not contained in $\cD_{W_1,W_2}$ and does not intersect ${\mathbb{P}}(W_1^\vee) \times {\mathbb{P}}(W_2^\vee)$.
Let $b_0 \in K$ be a bilinear form of rank 3 (it exists since ${\mathbb{P}}(K)$ is not contained in $\cD_{W_1,W_2}$).
Then $b_0$ identifies $W_2$ with $W_1^\vee$ and under this identification $b_0$ corresponds to the identity in ${\mathbb{P}}(W_1^\vee \otimes W_1) \cong {\mathbb{P}}(\End(W_1))$, 
so its zero locus is isomorphic to the flag variety $\Fl(1,2;W_1) \subset {\mathbb{P}}(W_1) \times {\mathbb{P}}(W_1^\vee)$. 
The subspace $K$ is then determined by an operator $b \in \End(W_1)$ defined up to a scalar multiple of the identity, and the condition that ${\mathbb{P}}(K)$ does not intersect ${\mathbb{P}}(W_1^\vee) \otimes {\mathbb{P}}(W_2^\vee)$
can be rephrased by saying that the pencil $\{b + t\id\}$ does not contain operators of rank~1.
From the Jordan Theorem it is clear that there are only three types of such $b$:
\begin{itemize}
\item[$(0)$]
$b$ is diagonal with three distinct eigenvalues;
\item[$(1)$]
$b$ has two Jordan blocks of sizes 2 and 1 with distinct eigenvalues; 
\item[$(2)$]
$b$ has one Jordan block of size 3.
\end{itemize}
It is easy to see that in case (0) the surface $X_b$ is smooth (hence of type 0), 
in case (1) it has one $A_1$ singularity (and is of type 2), and in case (3) it has one $A_2$ singularity (and is of type 4).

It remains to note that case (0) happens precisely when the line ${\mathbb{P}}(K)$ is transversal to $\cD_{W_1,W_2}$.
\end{proof}

Consider the universal family of codimension 2 linear sections of ${\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)$ that are sextic du Val del Pezzo surfaces.
According to Lemma~\ref{lemma:xk-duval} it can be described as follows.
Consider the Grassmannian~$\Gr(2,W_1^\vee \otimes W_2^\vee)$ parameterizing all two-dimensional subspaces $K \subset W_1^\vee \otimes W_2^\vee$, 
and its open subset parameterizing subspaces satisfying the conditions of Lemma~\ref{lemma:xk-duval}:
\begin{equation*}
S := \{ K \in \Gr(2,W_1^\vee \otimes W_2^\vee) \quad \mid \quad 
{\mathbb{P}}(K) \not\subset \cD_{W_1,W_2} \quand {\mathbb{P}}(K) \cap ({\mathbb{P}}(W_1^\vee) \times {\mathbb{P}}(W_2^\vee)) = \varnothing \}.
\end{equation*}
Let $\cK \subset W_1^\vee \otimes W_2^\vee \otimes \cO_S$ be the tautological rank 2 bundle, 
let $\cK^\perp \subset W_1 \otimes W_2 \otimes \cO_S$ be its rank~7 annihilator, and let 
\begin{equation}
\label{eq:cx-p2p2}
\cX := ({\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)) \times_{{\mathbb{P}}(W_1 \otimes W_2)} {\mathbb{P}}_S(\cK^\perp)
\end{equation}
be the corresponding du Val family of sextic del Pezzo surfaces.



\begin{proposition}
\label{proposition:dp-p2p2}
Let $\cX \to S$ be the du Val family of sextic del Pezzo surfaces defined by~\textup{\eqref{eq:cx-p2p2}}. 
Then 
\begin{equation*}
\cZ_2 = {\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \cD_{W_1,W_2},
\qquad 
\cZ_3 = S \sqcup S,
\end{equation*}
and the Brauer classes $\beta_{\cZ_2}$ and $\beta_{\cZ_3}$ are both trivial.
\end{proposition}
\begin{proof}
Using homological projective duality for ${\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)$, see Theorem~\ref{theorem:hpd-p2p2}, 
we obtain from~\cite[Theorem~6.27]{kuznetsov2007hpd} a semiorthogonal decomposition
\begin{equation*}
\bD(\cX) = \langle \Phi_{\cE_2}(\bD({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2)), \bD(S) \otimes \cO_\cX(1,0), \bD(S) \otimes \cO_\cX(0,1), \bD(S) \otimes \cO_\cX(1,1) \rangle,
\end{equation*}
where $\YY_2 \to \cD_{W_1,W_2}$ is the resolution of singularities defined in~\eqref{eq:def-yy2}, and
$\cE_2$ is the derived pullback of the sheaf $\EE_2$ defined by~\eqref{eq:hpd-kernel-xx3} with respect to the natural map 
\begin{equation}\label{eq:map-cx2}
\cX \times_S ({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2) \to \cX_2 \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2
\end{equation} 
(we will discuss this map below), where $\cX_2$ is the universal hyperplane section of ${\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)$.
Mutating the last component to the far left (note that $K_\cX = \cO_\cX(-1,-1)$ in the relative Picard group~$\Pic(\cX/S)$), we get
\begin{equation}
\label{eq:sod-cx-p2p2}
\bD(\cX) = \langle \bD(S) \otimes \cO_\cX, \Phi_{\cE_2}(\bD({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2)), \bD(S) \otimes \cO_\cX(1,0), \bD(S) \otimes \cO_\cX(0,1) \rangle.
\end{equation}
We claim that this decomposition agrees with the general decomposition~\eqref{eq:dbcx-again} of a du Val family of sextic del Pezzo surfaces.

Indeed, the last two components of~\eqref{eq:sod-cx-p2p2} can be considered as the derived category of~$S \sqcup S$ (the trivial double covering of $S$) embedded via the Fourier--Mukai functor with kernel
\begin{equation*}
\cE_3 := \cO_\cX(1,0) \sqcup \cO_\cX(0,1) \in \bD(\cX \sqcup \cX) = \bD(\cX \times_S (S \sqcup S)),
\end{equation*}
and the second component is the derived category of 
\begin{equation*}
{\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2 = {\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \cD_{W_1,W_2}
\end{equation*}
(recall that $\YY_2$ maps birationally onto $\cD_{W_1,W_2}$ and ${\mathbb{P}}_S(\cK)$ by definition of $S$ 
does not touch the indeterminacy locus ${\mathbb{P}}(W_1^\vee) \times {\mathbb{P}}(W_2^\vee)$ of that birational isomorphism),
which is a flat degree~3 covering of~$S$ (since $\cD_{W_1,W_2}$ is a hypersurface of degree~3), 
and it is embedded into~$\bD(\cX)$ via the Fourier--Mukai functor with kernel~$\cE_2$.

Let us check that both $\cE_2$ and $\cE_3$ are flat families of torsion-free rank 1 sheaves 
on fibers of~$\cX$ over~$S$ with Hilbert polynomials $h_2(t)$ and $h_3(t)$ respectively, parameterized by the schemes
\begin{equation*}
\cZ'_2 := {\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2
\qquand
\cZ'_3 := S \sqcup S.
\end{equation*}
For the second family flatness is clear and Hilbert polynomial computation is straightforward, so we skip it.
For the first family we note that the map~\eqref{eq:map-cx2} is flat.
Indeed, by~\eqref{eq:cx-p2p2} we have
\begin{equation*}
\cX \times_S ({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2) =
\Big(({\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)) \times_{{\mathbb{P}}(W_1 \otimes W_2)} {\mathbb{P}}_S(\cK^\perp)\Big) \times_S \Big({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2\Big),
\end{equation*}
while 
\begin{equation*}
\cX_2 \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2 = 
({\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)) \times_{{\mathbb{P}}(W_1 \otimes W_2)} Q \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2,
\end{equation*}
where $Q \subset {\mathbb{P}}(W_1 \otimes W_2) \times {\mathbb{P}}(W_1^\vee \otimes W_2^\vee)$ is the incidence quadric, so the map~\eqref{eq:map-cx2} is induced 
by the natural map ${\mathbb{P}}_S(\cK^\perp) \times_S {\mathbb{P}}_S(\cK) \to Q = \Fl(1,8;W_1^\vee \otimes W_2^\vee)$.
This map factors as 
\begin{equation*}
{\mathbb{P}}_S(\cK^\perp) \times_S {\mathbb{P}}_S(\cK) \hookrightarrow 
{\mathbb{P}}_{\Gr(2,W_1^\vee \otimes W_2^\vee)}(\cK^\perp) \times_{\Gr(2,W_1^\vee \otimes W_2^\vee)} {\mathbb{P}}_{\Gr(2,W_1^\vee \otimes W_2^\vee)}(\cK) = 
\Fl(1,2,8;W_1^\vee \otimes W_2^\vee) \to Q.
\end{equation*}
The first map is an open embedding, while the last map is a ${\mathbb{P}}^6$-bundle, so the composition is flat (and even smooth).

Recall the embedding of the Weil divisor $\YY_2 \times {\mathbb{P}}(W_2) \hookrightarrow \cX_2 \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2$ defined by~\eqref{diagram:yy-cx3}.
Its preimage under the map~\eqref{eq:map-cx2} is a Weil divisor in $\cX \times_S ({\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2)$ 
such that for any geometric point~$(K,b,w_1)$ of $\cZ'_2 := {\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2$ its fiber is the Weil divisor 
\begin{equation*}
L := X_K \times_{{\mathbb{P}}(W_1)} \{w_1\} \subset X_K,
\end{equation*}
i.e., a line on the sextic del Pezzo surface $X_K$ contracted by the projection $X_K \to {\mathbb{P}}(W_1)$ to the point~$\{w_1\} \in {\mathbb{P}}(W_1)$.
Thus, by~\eqref{eq:hpd-kernel-xx3}, the sheaf we are interested in is the twisted ideal $\cI_L \otimes \cO_{{\mathbb{P}}(W_1)}(1)$.
In particular, it is torsion-free, and its Hilbert polynomial equals~$h_2(t)$.

Therefore, the families of sheaves $\cE_2$ and $\cE_3$ induce maps 
\begin{equation*}
\mu_2 \colon \cZ'_2 \to \cZ_2(\cX/S)
\qquand 
\mu_3 \colon \cZ'_3 \to \cZ_3(\cX/S)
\end{equation*}
such that the Brauer classes $\mu_2^*(\beta_{\cZ_2})$ and $\mu_3^*(\beta_{\cZ_3})$ are trivial 
and $\cE_2$ and $\cE_3$ are isomorphic (up to twists by line bundles on~$\cZ'_2$ and $\cZ'_3$) 
to the pullbacks of the universal bundles $\cE_{\cZ_2}$ and $\cE_{\cZ_3}$, respectively.
This means that for $d \in \{2,3\}$ we have isomorphisms of Fourier--Mukai functors
\begin{equation*}
\Phi_{\cE_{d}} \cong \Phi_{\cE_{\cZ_d}} \circ \mu_{d*} \circ T_d \colon \bD(\cZ'_d) \to \bD(\cX),
\end{equation*}
where $T_d$ is a line bundle twist in $\bD(\cZ'_d)$.

Since both $\Phi_{\cE_{\cZ_d}}$ and $\Phi_{\cE_d}$ are fully faithful, 
so is the composition $\mu_{d*} \circ T_d \colon \bD(\cZ'_d) \to \bD(\cZ_d)$.
Moreover, comparing semiorthogonal decompositions given by~\eqref{eq:dbcx-again} and~\eqref{eq:sod-cx-p2p2}, we conclude that $\mu_{d*} \circ T_d$ is essentially surjective, i.e., an equivalence of categories.
Since $T_d$ is also an equivalence, we conclude that $\mu_{d*}$ is an equivalence, hence $\mu_d$ is an isomorphism.
Thus $\cZ'_d \cong \cZ_d(\cX/S)$ and the Brauer classes $\beta_{\cZ_2}$ and $\beta_{\cZ_3}$  on~$\cZ_2(\cX/S)$ and~$\cZ_3(\cX/S)$ vanish.
\end{proof}

\begin{remark}
\label{remark:extended-family}
Considering the family $\bar\cX \subset {\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2) \times \bar{S}$ of \emph{all} codimension 2 linear sections of~${\mathbb{P}}(W_1) \times {\mathbb{P}}(W_2)$ over $\bar{S} := \Gr(2,W_1^\vee \otimes W_2^\vee)$ 
and applying the semiorthogonal decomposition of Theorem~\ref{theorem:hpd-p2p2}, we obtain
\begin{equation*}
\bD(\bar\cX) = \langle \bD(\bar{S}), \bD(\bar{\cZ}_2), \bD(\bar{\cZ}_3) \rangle,
\end{equation*}
where $\bar{\cZ_2} = {\mathbb{P}}_S(\cK) \times_{{\mathbb{P}}(W_1^\vee \otimes W_2^\vee)} \YY_2$ and $\bar{\cZ_3} = \bar{S} \sqcup \bar{S}$.
Note that the map $\bar{\cZ_2} \to \bar{S}$ is not flat --- its non-flat locus $\bar{S} \setminus S$ is equal 
to the locus of non-integral fibers of the family $\bar{\cX} \to \bar{S}$.
\end{remark}



The statement of Proposition~\ref{proposition:dp-p2p2} can be inverted as follows.

\begin{lemma}
\label{lemma:reconstructing-family}
Let $\cX \to S$ be a du Val family of sextic del Pezzo surfaces.
If $\cZ_3(\cX/S) = S \sqcup S$ and the Brauer class $\beta_{\cZ_3}$ is trivial, 
then Zariski locally over $S$ the family $\cX \to S$ can be represented as a family of codimension $2$ linear sections of\/ ${\mathbb{P}}^2 \times {\mathbb{P}}^2$.
In particular, if $\cX$ is regular then $\beta_{\cZ_2}$ is trivial.
\end{lemma}
\begin{proof}
By Proposition~\ref{proposition:fd-md} there is a pair of rank 3 vector bundles $\cW_1$ and $\cW_2$ on $S$ such that
\begin{equation*}
F_3(\cX/S) = {\mathbb{P}}_S(\cW_1) \sqcup {\mathbb{P}}_S(\cW_2).
\end{equation*}
Moreover, the restrictions of the universal sheaf $\cE_{\cZ_3}$ on $\cX \times_S \cZ_3 = \cX \sqcup \cX$ to the two components are line bundles defining regular maps $\cX \to {\mathbb{P}}_S(\cW_1)$ and $\cX \to {\mathbb{P}}_S(\cW_2)$ respectively.
Thus, the induced map 
\begin{equation*}
\cX \to {\mathbb{P}}_S(\cW_1) \times_S {\mathbb{P}}_S(\cW_2)
\end{equation*}
is a closed embedding.
Zariski locally the bundles $\cW_1$ and $\cW_2$ are trivial, hence we obtain the required local presentation of $\cX$.
The Brauer class $\beta_{\cZ_2}$ vanishes Zariski locally by Proposition~\ref{proposition:dp-p2p2}
and~$\cZ_2$ is regular by Proposition~\ref{proposition:smoothness}, hence $\beta_{\cZ_2} = 0$.
\end{proof}

A slightly more general family of sextic del Pezzo surfaces can be obtained by replacing the projective spaces ${\mathbb{P}}(W_1)$ and ${\mathbb{P}}(W_2)$ 
by a pair of projectively dual (i.e., corresponding to mutually inverse Brauer classes) Severi--Brauer surfaces.
In this way one can obtain a family of sextic del Pezzo surfaces with a nontrivial Brauer class $\beta_{\cZ_3}$ 
(however, this class will be ``constant in a family'').
Another possible generalization, is to consider a double covering $\tS \to S$ and a Brauer class $\beta$ on $\tS$ of order~3 
such that~$\beta = \sigma^*(\beta^{-1})$, 
where $\sigma \colon \tS \to \tS$ is the involution of the double covering 
(cf.~the isomorphism of Brauer classes in Proposition~\ref{proposition:md-zd}).
Then one can apply the Weil restriction of scalars to obtain an \'etale locally trivial fibration over $S$ 
with fibers ${\mathbb{P}}^2 \times {\mathbb{P}}^2$, and then consider its linear section of codimension~2.

Hyperplane sections of ${\mathbb{P
}^1 \times {\mathbb{P}}^1 \times {\mathbb{P}}^1$}
\label{subsection:p1p1p1}

Another simple way to construct a sextic del Pezzo surface is by considering a hyperplane section of ${\mathbb{P}}^1 \times {\mathbb{P}}^1 \times {\mathbb{P}}^1$ in the Segre embedding.

We denote by $V_1$, $V_2$, and $V_3$ three vector spaces of dimension 2 and let 
\begin{equation*}
{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}(V_3) \hookrightarrow {\mathbb{P}}(V_1 \otimes V_2 \otimes V_3)
\end{equation*}
be the Segre embedding. 
For a trilinear form $b \in V_1^\vee \otimes V_2^\vee \otimes V_3^\vee$ we denote by
\begin{equation}\label{eq:xb}
X_b := ({\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}(V_3)) \cap {\mathbb{P}}(b^\perp) \subset {\mathbb{P}}(V_1 \otimes V_2 \otimes V_3) 
\end{equation}
the corresponding hyperplane section, where $b^\perp \subset V_1 \otimes V_2 \otimes V_3$ is the annihilator hyperplane of $b$.

Recall that the group $\rG := (\PGL(V_1) \times \PGL(V_2) \times \PGL(V_3)) \rtimes \fS_3$ acts on ${\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)$ with four orbits.
The orbits closures are:
\begin{itemize}
\item $\rO_3 = {\mathbb{P}}(V_1^\vee) \times {\mathbb{P}}(V_2^\vee) \times {\mathbb{P}}(V_3^\vee)$;
\item $\overline\rO_4 = ({\mathbb{P}}(V_1^\vee) \times {\mathbb{P}}(V_2^\vee \otimes V_3^\vee)) \cup ({\mathbb{P}}(V_2^\vee) \times {\mathbb{P}}(V_1^\vee \otimes V_3^\vee)) \cup ({\mathbb{P}}(V_3^\vee) \times {\mathbb{P}}(V_1^\vee \otimes V_2^\vee))$;
\item $\overline\rO_6 = ({\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}(V_3))^\vee$ is the projectively dual quartic hypersurface; and
\item $\overline\rO_7 = {\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)$
\end{itemize}
(we use the dimensions of the orbits as indices).
The equation of the quartic hypersurface $\overline\rO_6$ is given by the Cayley's hyperdeterminant, see~\cite[14.1.7]{gkz1994}.

\begin{lemma}\label{lemma:xb-duval}
Assume the base field $\kk$ is algebraically closed.
The hyperplane section $X_b$ defined by~\textup{\eqref{eq:xb}} is a sextic du Val del Pezzo surface if and only if $b \in {\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee) \setminus \overline\rO_4$.
Furthermore, $X_b$ is smooth if and only if $b \in {\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee) \setminus \overline\rO_6$.
\end{lemma}
\begin{proof}
Indeed, choosing a representative of each orbit, it is easy to see that 
$X_b$ is smooth, if $b \in \rO_7$; 
has one $A_1$ singularity (and is of type 1), if $b \in \rO_6$;
is a union of a smooth quadric and a quartic scroll, if~$b \in \rO_4$; 
and is a union of three quadrics, if $b \in \rO_3$.
\end{proof}

Consider the universal family of hyperplane sections of ${\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}(V_3)$ that are sextic du Val del Pezzo surfaces.
By Lemma~\ref{lemma:xb-duval} it can be described as follows.
Consider the open subset 
\begin{equation*}
S := \rO_6 \cup \rO_7 = {\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee) \setminus \overline\rO_4 \subset {\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee).
\end{equation*}
Let $\cL \subset V_1^\vee \otimes V_2^\vee \otimes V_3^\vee \otimes \cO_S$ be the tautological line bundle, let $\cL^\perp \subset V_1 \otimes V_2 \otimes V_3 \otimes \cO_S$ be its rank 7 annihilator, and let 
\begin{equation}\label{eq:cx-p1p1p1}
\cX := ({\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}(V_3)) \times_{{\mathbb{P}}(V_1 \otimes V_2 \otimes V_3)} {\mathbb{P}}_S(\cL^\perp)
\end{equation}
be the corresponding du Val family of sextic del Pezzo surfaces.


Denote by ${\cD_{V_1,V_2,V_3}} \to {\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)$ the double covering branched along the Cayley quartic hypersurface~$\overline\rO_6$.

\begin{proposition}\label{proposition:dp-p1p1p1}
Let $\cX \to S$ be the du Val family of sextic del Pezzo surfaces defined by~\textup{\eqref{eq:cx-p1p1p1}}. 
Then 
\begin{equation*}
\cZ_2 = S \sqcup S \sqcup S,
\qquad 
\cZ_3 = S \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} {\cD_{V_1,V_2,V_3}},
\end{equation*}
and the Brauer classes $\beta_{\cZ_2}$ and $\beta_{\cZ_3}$ are both trivial.
\end{proposition}
\begin{proof}
The proof is parallel to that of Proposition~\ref{proposition:dp-p2p2}.

Using homological projective duality for ${\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}(V_3)$, see Theorem~\ref{theorem:hpd-p1p1p1}, 
we obtain from~\cite[Theorem~6.27]{kuznetsov2007hpd} a semiorthogonal decomposition
\begin{multline*}
\bD(\cX) = \langle \Phi_{\cE_3}(\bD(S \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} \YY_3)), \\
\bD(S) \otimes \cO_\cX(1,1,1), \bD(S) \otimes \cO_\cX(2,1,1), \bD(S) \otimes \cO_\cX(1,2,1), \bD(S) \otimes \cO_\cX(1,1,2) \rangle,
\end{multline*}
where $\YY_3 \to \cD_{V_1,V_2,V_3}$ is the resolution of singularities defined in~\eqref{eq:def-yy3} and
where $\cE_3$ is the derived pullback of the sheaf $\EE_3$ defined by~\eqref{eq:hpd-kernel-xxx3} with respect to the natural map 
\begin{equation}\label{eq:map-cx3}
\cX \times_S (S \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} \YY_3) \to \cX_3 \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} \YY_3
\end{equation} 
(we will discuss this map below).
Mutating the last four components to the far left 
(again, note that~\mbox{$K_\cX = \cO_\cX(-1,-1,-1)$} in the relative Picard group~$\Pic(\cX/S)$), we get
\begin{multline}
\bD(\cX) = \langle \bD(S) \otimes \cO_\cX, \bD(S) \otimes \cO_\cX(1,0,0), \bD(S) \otimes \cO_\cX(0,1,0), \bD(S) \otimes \cO_\cX(0,0,1), \\
\Phi_{\cE_3}(\bD(S \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} \YY_3)) \rangle.
\end{multline}
We claim that this decomposition agrees with the general decomposition~\eqref{eq:dbcx-again} for a du Val family of sextic del Pezzo surfaces.
Indeed, its second, third and fourth components can be considered as the derived category of $S \sqcup S \sqcup S$ (the trivial triple covering of $S$) embedded via the Fourier--Mukai functor with kernel
\begin{equation*}
\cE_2 := \cO_\cX(1,0,0) \sqcup \cO_\cX(0,1,0) \sqcup \cO_\cX(0,0,1) \in \bD(\cX \sqcup \cX \sqcup \cX) = \bD(\cX \times_S (S \sqcup S \sqcup S)),
\end{equation*}
while the last component is the derived category 
of~$S \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} \YY_3 = 
S \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} {\cD_{V_1,V_2,V_3}}$
(recall that $\YY_3$ maps birationally onto ${\cD_{V_1,V_2,V_3}}$ and $S$ by definition 
does not touch the image $\overline\rO_4$ (see Remark~\ref{remark:fibers-resolution-dvvv}) 
of the indeterminacy locus of that birational isomorphism),
which is a flat degree~2 covering of~$S$ (since ${\cD_{V_1,V_2,V_3}}$ is flat over the complement of~$\overline\rO_4$), 
and it is embedded into~$\bD(\cX)$ via the Fourier--Mukai functor with kernel~$\cE_3$.

Let us check that both $\cE_2$ and $\cE_3$ are flat families of torsion-free rank 1 sheaves on the fibers of $\cX$ over~$S$ with Hilbert polynomials $h_2(t)$ and $h_3(t)$ respectively, parameterized by 
\begin{equation*}
\cZ'_2 := S \sqcup S \sqcup S
\qquand
\cZ'_3 := S \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} \YY_3.
\end{equation*}
For the first flatness is clear and Hilbert polynomial computation is straightforward, so we skip it.
For the second we note that the map~\eqref{eq:map-cx3} is flat.
Indeed, arguing as in the proof of Proposition~\ref{proposition:dp-p2p2} we can check
that the map~\eqref{eq:map-cx3} is obtained by base change from the map 











\begin{equation*}
{\mathbb{P}}_S(\cL^\perp) \times_S {\mathbb{P}}_S(\cL) \to Q = \Fl(1,7;V_1^\vee \otimes V_2^\vee \otimes V_3^\vee) 
\end{equation*}
which is an open embedding.

Recall the embedding of the Weil divisor $\YY_3 \times {\mathbb{P}}(V_3) \hookrightarrow \cX_3 \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} \YY_3$ defined by~\eqref{diagram:yy-cx}.
The preimage of $\YY_3 \times {\mathbb{P}}(V_3)$ under~\eqref{eq:map-cx3} is a Weil divisor in $\cX \times_S (S \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} \YY_3)$ 
such that for any closed point $(b,v_1,v_2)$ of $\cZ'_3 = S \times_{{\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)} \YY_3$ its fiber is the Weil divisor 
\begin{equation*}
L := X_b \times_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)} \{(v_1,v_2)\} \subset X_b,
\end{equation*}
i.e., a line on the sextic del Pezzo surface $X_b$ contracted by the projection $X_b \to {\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)$ 
to the point $(v_1,v_2) \in {\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)$.
Thus, by~\eqref{eq:hpd-kernel-xxx3}, the sheaf we are interested in is the twisted ideal \mbox{$\cI_L \otimes \cO_{{\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2)}(1,1)$}.
In particular, it is torsion-free, and its Hilbert polynomial equals~$h_3(t)$.

The rest of the proof repeats the argument of Proposition~\ref{proposition:dp-p2p2}.
\end{proof}

The statement of Proposition~\ref{proposition:dp-p1p1p1} can be inverted as follows (and the proof repeats the proof of Lemma~\ref{lemma:reconstructing-family}).

\begin{lemma}
Let $\cX \to S$ be a du Val family of sextic del Pezzo surfaces.
If $\cZ_2(\cX/S) = S \sqcup S \sqcup S$ and the Brauer class $\beta_{\cZ_2}$ is trivial, then Zariski locally over $S$ 
the family $\cX \to S$ can be represented as a family of hyperplane sections of\/ ${\mathbb{P}}^1 \times {\mathbb{P}}^1 \times {\mathbb{P}}^1$.
In particular, if $\cX$ is regular then $\beta_{\cZ_3}$ is trivial.
\end{lemma}

Moreover, for any $\cF \in \Ker\pi_* \subset \bD^-(\tX)$ there is a canonical direct sum decomposition 
\begin{equation*}
\cF = \cF_2 \oplus \cF_3
\end{equation*}
with $\cF_j \in \tcA_j^- \cap \Ker \pi_*$.
\end{lemma}
\begin{proof}
By Lemma~\ref{lemma:pi-properties}
an object $\cF \in \bD^-(\tX)$ is in $\Ker\pi_*$ if and only if every its cohomology sheaf~$\cH^j(\cF)$ 
is an iterated extension of sheaves $\cO_\Delta(-1)$
where $\Delta$ run over the set $\bDelta$ of all $(-2)$-curves on~$\tX$.
Note that $\cO_\Delta(-1) \in \tcA_2$ for $\Delta \in \bDelta_2$ by~\eqref{eq:e12} and~\eqref{eq:e23}, while $\cO_\Delta(-1) \in \tcA_3$ for $\Delta \in \bDelta_3$ by~\eqref{eq:e123}.
Moreover, the subcategories generated by the sheaves $\cO_\Delta(-1)$ with $\Delta \in \bDelta_2$ and $\Delta \in \bDelta_3$ are completely orthogonal, since the supports of these sheaves do not intersect.
This last observation shows that any $\cF \in \Ker\pi_*$ decomposes as $\cF_2 \oplus \cF_3$ with the required properties (just take $\cF_2$ and $\cF_3$ to be the components of $\cF$ 
supported on the union of the curves $\Delta$ from $\bDelta_2$ and $\bDelta_3$ respectively).
\end{proof}

Moreover, $\pi_*(\cG_j) \in \pi_*(\tilde\gamma_j(\bD(\tR_{m_j}))) = \gamma_j(\bD(\kk[t]/t^m))$,
hence objects $\cF_j = \pi_*(\cG_j)$ give the required decomposition of $\cF$.
\end{proof}

Moreover, this semiorthogonal decomposition 
is right mutation-dual to~\eqref{eq:dbx}, i.e., $\cA_1^\vee = \cA_1$, $\cA_2^\vee = \LL_{\cA_1}(\cA_2)$ and $\cA_3^\vee = \LL_{\cA_1}(\LL_{\cA_2}(\cA_3))$.
\end{proposition}
\begin{proof}
As we discussed in Section~\ref{subsection:duality}, the functor $\cF \mapsto \cF^\vee$ is an equivalence $\bD(X)^{\mathrm{opp}} \to \bD(X)$ (since~$X$ is Gorenstein).
When applied to the semiorthogonal decomposition of Corollary~\ref{corollary:dbx-z2-z3}, it gives~\eqref{eq:dbx-dual} 
with~$\cA_i^\vee \cong \bD(Z_i)^{\mathrm{opp}}$.
Since $Z_1$, $Z_2$ and $Z_3$ are themselves Gorenstein, we have $\bD(Z_i)^{\mathrm{opp}} \cong \bD(Z_i)$.

Moreover, $\fE_Z$ is an iterated extension of the sheaf $\cE_z$, where $z$ is the closed point of~$Z$.
In particular, the bundle $\fE_Z$ is globally generated with $\dim H^0(X,\fE_Z) = d\ell(Z)$ and $H^i(X,\fE_Z) = 0$ for $i \ne 0$.
\end{proposition}
\begin{proof}
First, by commutativity of~\eqref{eq:gamma-tgamma} we have $\tfE_Z \cong \tilde\gamma_Z(\pi_m^*(\cO_Z))$.
Furthermore, $\pi_m^*(\cO_Z) \cong P_0$, the principal projective module, see~\eqref{eq:pms}, so that
\begin{equation}\label{eq:tcez-p0}
\tfE_Z \cong \tilde\gamma_Z(P_0).
\end{equation}
By~\eqref{eq:projective-resolution-ei} the module $P_0$ is an iterated extension of the standard exceptional modules $E_i$, 
hence $\tilde\gamma_Z(P_0)$ is an iterated extension of $\tilde\gamma_Z(E_i)$, 
and as it is explained in the proof of Proposition~\ref{proposition:tcai-auslander} these are line bundles on $\tX$.
More precisely, if $Z$ is reduced, then 
\begin{equation*}
\tfE_Z \cong \cO_\tX(h-e_i)\quad\text{for some $i$},\quad\text{or}\quad 
\tfE_Z \cong \cO_\tX(h),\quad\text{or}\quad
\tfE_Z \cong \cO_\tX(2h-e_1-e_2-e_3),
\end{equation*}
depending on whether $Z$ is a component of $Z_2$ or of $Z_3$.
Furthermore, if $Z$ has length~2 then we have exact sequences
\begin{equation}\label{eq:tcez-12}
0 \to \cO_\tX(h-e_2) \to \tfE_Z \to \cO_\tX(h-e_1) \to 0,
\end{equation}
when $Z$ is a component of $Z_2$, or
\begin{equation}\label{eq:tcez-123}
0 \to \cO_\tX(2h-e_1-e_2-e_3) \to \tfE_Z \to \cO_\tX(h) \to 0,
\end{equation}
when $Z$ is a component of $Z_3$.
Finally, if $Z$ has length~3 we have two exact sequences
\begin{equation}\label{eq:tcez-12-23}
0 \to \cO_\tX(h-e_3) \to \tfE_Z \to \tfE'_Z \to 0,
\qquad\text{where}\qquad
0 \to \cO_\tX(h-e_2) \to \tfE'_Z \to \cO_\tX(h-e_1) \to 0.
\end{equation}
In all cases $\tfE_Z$ is evidently a vector bundle of rank~$\ell(Z)$, 
and since $\tfE_Z \cong \pi^*\fE_Z$, it follows that $\fE_Z$ is also a vector bundle of the same rank~$\ell(Z)$.
Finally, since $Z \cong \Spec(\kk[t]/t^m)$, the sheaf $\cO_Z$ is an iterated extension of the sheaf $\cO_z$,
