Consider the universal family of hyperplane sections of ${\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}(V_3)$ that are sextic du Val del Pezzo surfaces.
By Lemma~\ref{lemma:xb-duval} it can be described as follows.
Consider the open subset 
\begin{equation*}
S := \rO_6 \cup \rO_7 = {\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee) \setminus \overline\rO_4 \subset {\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee).
\end{equation*}
Let $\cL \subset V_1^\vee \otimes V_2^\vee \otimes V_3^\vee \otimes \cO_S$ be the tautological line bundle, let $\cL^\perp \subset V_1 \otimes V_2 \otimes V_3 \otimes \cO_S$ be its rank 7 annihilator, and let 
\begin{equation}\label{eq:cx-p1p1p1}
\cX := ({\mathbb{P}}(V_1) \times {\mathbb{P}}(V_2) \times {\mathbb{P}}(V_3)) \times_{{\mathbb{P}}(V_1 \otimes V_2 \otimes V_3)} {\mathbb{P}}_S(\cL^\perp)
\end{equation}
be the corresponding du Val family of sextic del Pezzo surfaces.


Denote by ${\cD_{V_1,V_2,V_3}} \to {\mathbb{P}}(V_1^\vee \otimes V_2^\vee \otimes V_3^\vee)$ the double covering branched along the Cayley quartic hypersurface~$\overline\rO_6$.

\begin{proof}
Using~\eqref{eq:projective-resolution-ei} we see that $\Ext^\bullet(E_i,E_j)$ is computed by the complex
\begin{equation*}
(E_j)_i \xrightarrow{\ \beta_{i+1}\ } (E_j)_{i+1}.
\end{equation*}
If $i > j$ both spaces are zero and if $i = j$ the first is $\kk$ and the second is zero, hence the collection is exceptional.
Similarly, if $j > i$ both spaces are $\kk$ and the arrow is zero, hence $\Hom(E_i,E_j) = \Ext^1(E_i,E_j) = \kk$.

For the second statement, note that we have an exact sequence
\begin{equation}\label{eq:resolution-simple}
0 \to E_{i-1} \xrightarrow{\ \alpha_i\ } E_i \to S_i \to 0,
\end{equation} 
which shows that for $j \le k$ the natural map $E_j \to E_k$ is injective and its cokernel is an extension of simple modules $S_l$ with $j+1 \le l \le k$.
On the other hand, \eqref{eq:projective-resolution-ei} implies that $\Ext^\bullet(E_i,S_l) = 0$ as soon as~$l \ge i+2$, hence the map 
\begin{equation*}
\Ext^\bullet(E_i,E_j) \to \Ext^\bullet(E_i,E_k)
\end{equation*}
induced by the embedding $E_j \to E_k$ is an isomorphism. This proves the case when $q = 0$.

Similarly, merging~\eqref{eq:resolution-simple} with~\eqref{eq:projective-resolution-ei} we obtain for $l \ge 1$ a projective resolution
\begin{equation}\label{eq:projective-resolution-simples}
0 \to P_l \xrightarrow{\ (-\alpha_{l+1},\beta_l)\ } P_{l+1} \oplus P_{l-1} \xrightarrow{\ (\beta_{l+1},\alpha_l)\ } P_l \to S_l \to  0
\end{equation}
of the simple module $S_l$.
It follows that $\Ext^\bullet(S_l,E_k)$ for $1 \le l < k$ are computed by the complex
\begin{equation*}
(E_k)_l \xrightarrow{\ (0,1)\ } (E_k)_{l+1} \oplus (E_k)_{l-1} \xrightarrow{\ (-1,0)} (E_k)_l,
\end{equation*}
hence for $1 \le l < k$ we have $\Ext^\bullet(S_l,E_k) = 0$.
On the other hand, the cokernel of the embedding $E_i \to E_j$ is an extension of simple modules $S_l$ with $1 \le l \le j$, hence the map 
\begin{equation*}
\Ext^\bullet(E_j,E_k) \to \Ext^\bullet(E_i,E_k)
\end{equation*}
induced by this embedding is an isomorphism. This proves the case when $p = 0$.
\end{proof}

The following characterization of the categories $\bD(\tR_2)$ and $\bD(\tR_3)$ is quite useful.

\begin{proof}
Since the category $\cT$ is enhanced, there is an equivalence of $\cT$ with the derived category of the DG algebra $\RHom_\cT(\oplus \cL_i,\oplus \cL_i)$.
By the assumption, its cohomology is isomorphic (as a graded algebra) to the graded algebra $\Ext^\bullet_{\bD(\tR_m)}(\oplus E_i, \oplus E_i)$.
To get the desired equivalence, it remains to check that the latter algebra (considered as a DG algebra with trivial differential) is formal.

But formality is clear, since any higher $A_\infty$-operation $\bm_i$ (with $i \ge 3$) requires at least three non-trivial arguments, 
so one needs the quiver to have at least four vertices to admit such an operation.
So, for $\tR_2$ and $\tR_3$ all higher operations vanish and the algebra is formal.
\end{proof}

\begin{remark}
Let $m \ge 4$ and assume $\cT$ is an enhanced triangulated category generated by an exceptional collection $\cL_0,\cL_1,\dots,\cL_{m-1}$ satisfying the properties of Lemma~\ref{lemma:auslander-ext-ei}.
To establish an equivalence of $\cT$ with~$\bD(\tR_m)$ one should additionally check that higher $A_\infty$-operations in $\cT$ vanish when one of the arguments is contained in the space $\Hom(\cL_i,\cL_{i+1}) = \kk$.
\end{remark}



The endomorphism algebra of the projective module $P_0$ is
\begin{equation*}
\End_{\tR_m}(P_0) = \epsilon_0 \tR_m \epsilon_0 = (\tR_m)_{00} = \kk[t]/t^m.
\end{equation*}
Using this we define an adjoint pair of functors
\begin{equation}
\label{eq:pms}
\begin{aligned}
\pi_{m*} & \colon \tR_m\mmod \to (\kk[t]/t^m)\mmod, \quad & M & \mapsto \Hom_{\tR_m}(P_0,M) = \epsilon_0 M,\\
\pi_m^* & \colon (\kk[t]/t^m)\mmod \to \tR_m\mmod, \quad & N & \mapsto P_0 \otimes_{\kk[t]/t^m} N.
\end{aligned}
\end{equation} 
Following our convention, we denote in the same way their derived functors.

Note that the functor $\pi_{m*} \colon \bD(\tR_m) \to \bD(\kk[t]/t^m)$ preserves boundedness, while its left adjoint $\pi_m^*$ does not.
Recall that $\langle - \rangle^\oplus$ denotes the minimal triangulated subcategory of $\bD^-(\tR_m)$ closed under infinite direct sums.

\begin{proof}
Let ${\cX_2} \subset {\XX_2} \times {\mathbb{P}}(\WW^\vee)$ be the universal hyperplane section of ${\XX_2}$.
By~\cite[Theorem~8.2]{kuznetsov2007hpd}, there is a semiorthogonal decomposition
\begin{equation}
\label{eq:dbxx3-1}
\bD({\cX_2}) = \langle i_*\phi^*(\bD({\YY_2})), \bD({\mathbb{P}}(W_1) \times {\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,1), \bD({\mathbb{P}}(W_1) \times {\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(2,2) \rangle,
\end{equation}
where the morphisms $i$ and $\phi$ are defined by the Cartesian diagram
\begin{equation}
\label{diagram:yy-cx3}
\vcenter{\xymatrix{
{\YY_2} \times {\mathbb{P}}(W_2) \ar[r]^-i \ar[d]_\phi & {\cX_2} \ar[d]^{p_{\cX_2}} \\
{\YY_2} \ar[r]^-{p_{\YY_2}} & {\mathbb{P}}(W_1) \times {\mathbb{P}}(\WW^\vee) \ar[r]^-{p_2} & {\mathbb{P}}(\WW^\vee)
}}
\end{equation}
and the map $p_{\YY_2}$ is induced by the embedding $\cW_2^\perp \hookrightarrow \WW^\vee \otimes \cO_{{\mathbb{P}}(W_1)}$.
We modify~\eqref{eq:dbxx3-1} by a sequence of mutations to change it to the form we need.

First, using the standard exceptional collection $\bD({\mathbb{P}}(W_1)) = \langle \cO_{{\mathbb{P}}(W_1)}(-1), \cO_{{\mathbb{P}}(W_1)}, \cO_{{\mathbb{P}}(W_1)}(1) \rangle$,
decomposition \eqref{eq:dbxx3-1} can be rewritten as
\begin{multline*}
\bD({\cX_2}) = \langle i_*\phi^*(\bD({\YY_2})), \\ 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(0,1), 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,1), 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(2,1), \\
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,2), 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(2,2), 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(3,2)
\rangle.
\end{multline*}
Mutating the last component to the far left and taking into account that $\omega_{\cX_2} \cong \cO_{\XX_2}(-2,-2)$ up to a line bundle pulled back from ${\mathbb{P}}(\WW^\vee)$, we obtain a semiorthogonal decomposition
\begin{multline*}
\bD({\cX_2}) = \langle \bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,0),
i_*\phi^*(\bD({\YY_2})), \\ 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(0,1), 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,1), \\
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(2,1), 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,2), 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(2,2)
\rangle.
\end{multline*}

Next, mutating the second component one step to the left, we get
\begin{multline}\label{eq:dbxx3-2}
\bD({\cX_2}) = \langle \Phi(\bD({\YY_2})), \\
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,0),
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(0,1), 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,1), \\
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(2,1), 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,2), 
\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(2,2)
\rangle.
\end{multline}
where $\Phi = \LL_{\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,0)} \circ i_* \circ \phi^* \colon \bD({\YY_2}) \to \bD({\cX_2})$.

This almost proves the result. 
The only small thing left is to show that the functor $\Phi$ is a Fourier--Mukai functor 
whose kernel is supported on the fiber product ${\YY_2} \times_{{\mathbb{P}}(\WW^\vee)} {\cX_2}$.
For this we note that by~\eqref{diagram:yy-cx3} the functor $i_* \circ \phi^*$ is a Fourier--Mukai functor 
with kernel $j_*\cO_{{\YY_2} \times {\mathbb{P}}(W_2)}$, 
where $j \colon \YY_2 \times {\mathbb{P}}(W_2) \to \YY_2 \times_{{\mathbb{P}}(\WW^\vee)} \cX_2$ is the embedding 
induced by the commutative square~\eqref{diagram:yy-cx3}.
Moreover, using notation from the diagram~\eqref{diagram:yy-cx3}, 
the projection functor onto $\bD({\mathbb{P}}(\WW^\vee)) \otimes \cO_{\XX_2}(1,0)$ is given by
\begin{equation*}
\cF \mapsto p_{\cX_2}^*(p_2^*p_{2*}(p_{\cX_2*}\cF \otimes \cO_{{\mathbb{P}}(W_1)}(-1)) \otimes \cO_{{\mathbb{P}}(W_1)}(1)),
\end{equation*}
and its composition with $i_* \circ \phi^*$ is given by
\begin{equation*}
\cF \mapsto p_{\cX_2}^*(p_2^*p_{2*}(p_{\YY_2*}\cF \otimes \cO_{{\mathbb{P}}(W_1)}(-1)) \otimes \cO_{{\mathbb{P}}(W_1)}(1)).
\end{equation*}
In other words, this composition is a Fourier--Mukai functor with kernel $p_{\YY_2}^*(\cO_{{\mathbb{P}}(W_1)}(-1)) \boxtimes p_{\cX_2}^*(\cO_{{\mathbb{P}}(W_1)}(1))$ on $\YY_2 \times_{{\mathbb{P}}(\WW^\vee)} \cX_2$.
Therefore, the functor $\Phi$ fits into a distinguished triangle
\begin{equation*}
\Phi_{p_{\YY_2}^*(\cO_{{\mathbb{P}}(W_1)}(-1)) \boxtimes p_{\cX_2}^*(\cO_{{\mathbb{P}}(W_1)}(1))} \to \Phi_{j_*\cO_{{\YY_2} \times {\mathbb{P}}(W_2)}} \to \Phi.
\end{equation*}
It follows from~\eqref{diagram:yy-cx3} that 
\begin{equation*}
j^*(p_{\YY_2}^*(\cO_{{\mathbb{P}}(W_1)}(-1)) \boxtimes p_{\cX_2}^*(\cO_{{\mathbb{P}}(W_1)}(1))) \cong \cO_{{\YY_2} \times {\mathbb{P}}(W_2)}, 
\end{equation*}
hence by~\cite{anno2012adjunction} the above triangle of functors is induced by (a rotation of the twist of) 
the triangle associated with the standard exact sequence
\begin{equation*}
0 \to \cI_{{\YY_2} \times {\mathbb{P}}(W_2), {\YY_2} \times_{{\mathbb{P}}(\WW^\vee)} {\cX_2}} \to \cO_{{\YY_2} \times_{{\mathbb{P}}(\WW^\vee)} {\cX_2}} \to j_*\cO_{{\YY_2} \times {\mathbb{P}}(W_2)} \to 0.
\end{equation*}
It finally proves, that up to an irrelevant shift, the functor $\Phi$ is indeed a Fourier--Mukai functor with the kernel
\begin{equation}\label{eq:hpd-kernel-xx3}
\EE_2 := \cI_{{\YY_2} \times {\mathbb{P}}(W_2), {\YY_2} \times_{{\mathbb{P}}(\WW^\vee)} {\cX_2}} \otimes (p_{\YY_2}^*(\cO_{{\mathbb{P}}(W_1)}(-1)) \boxtimes p_{\cX_2}^*(\cO_{{\mathbb{P}}(W_1)}(1))) \in \bD({\YY_2} \times_{{\mathbb{P}}(\WW^\vee)} \cX_2),
\end{equation}
and thus completes the proof of the theorem.
\end{proof}

\begin{remark}
We could, of course, exchange the role of $W_1$ and $W_2$ in the construction.
Then we would get a slightly different homological projectively dual variety as the result, that is
\begin{equation*}
\YY_2' = {\mathbb{P}}_{{\mathbb{P}}(W_2)}(W_1^\vee \otimes \Omega_{{\mathbb{P}}(W_2)}(1)).
\end{equation*}
Note that the natural maps $\YY_2 \to {\mathbb{P}}(\WW^\vee)$ and $\YY_2' \to {\mathbb{P}}(\WW^\vee)$ are birational onto the same discriminant cubic hypersurface $\cD_{W_1,W_2} \subset {\mathbb{P}}(\WW^\vee) = {\mathbb{P}}(W_1^\vee \otimes W_2^\vee)$
and provide two small resolutions of singularities of~$\cD_{W_1,W_2}$, related to each other by a flop, identifying their derived categories.
So, the homological projectively dual of $\XX_2$ as a category is unambiguously defined, but has two different geometric models~$\YY_2$ and~$\YY_2'$, breaking down its inner symmetry.
\end{remark}

One can also use the above result to construct a symmetric homological projective duality 
for the flag variety $\Fl(W) = \Fl(1,2;W)$ of a three-dimensional vector space $W$.
Note that $\Fl(W)$ is a smooth hyperplane section of ${\mathbb{P}}(W) \times {\mathbb{P}}(W^\vee)$ corresponding 
to the natural bilinear pairing $b_0$ between $W$ and~$W^\vee$.
Since~$b_0$ is nondegenerate, it does not lie in the image $\cD_{W,W^\vee}$ of $\YY_2$ in ${\mathbb{P}}(W \otimes W^\vee)$, 
hence by homological projective duality \cite[Theorem~6.3]{kuznetsov2007hpd} we obtain a semiorthogonal decomposition
\begin{equation*}
\bD(\Fl(W)) = \langle \cO_{\Fl(W)}(0,-1), \cO_{\Fl(W)}(-1,0), \cO_{\Fl(W)}, \cO_{\Fl(W)}(1,0), \cO_{\Fl(W)}(0,1), \cO_{\Fl(W)}(1,1) \rangle. 
\end{equation*}
Clearly, this is a Lefschetz collection with respect to $\cO_{\Fl(W)}(1,1)$ with two blocks equal to 
\begin{equation}\label{eq:flw-lefschetz}
\cA_{\Fl(W)}^{\rm{sym}} = \langle \cO_{\Fl(W)}(0,-1), \cO_{\Fl(W)}(-1,0), \cO_{\Fl(W)} \rangle. 
\end{equation}
On the other hand, the linear projection with center at $b_0$ defines a regular map $\YY_2 \to {\mathbb{P}}((W \otimes W^\vee)/b_0)$.

\begin{proof}
Follows from Theorem~\ref{theorem:hpd-p2p2} by~\cite[Theorem~3.4]{carocci2015homological}. 
(see also~\cite[Proposition~A.10]{kuznetsov2018cones}).

\end{proof}

